window.JLPTDATA=window.JLPTDATA||{};window.JLPTDATA["grammar"]=[{"id":"kara-from","pattern":"〜から（from）","romaji":"kara (from)","level":"N5","ru":"из; с; от (начальная точка во времени или в пространстве)","en":"from (a starting point in time or place)","formation":"Noun + から","formationRu":"существительное + から","notes":"Часто идёт в паре с まで: 月曜日から金曜日まで (с понедельника по пятницу).","tags":["particle","time","range"],"ex":[{"ja":"授業は9時からです。","fu":"{授業|じゅぎょう}は9{時|じ}からです。","ru":"Занятия начинаются с 9 часов."},{"ja":"学校から駅まで歩きます。","fu":"{学校|がっこう}から{駅|えき}まで{歩|ある}きます。","ru":"От школы до вокзала я иду пешком."},{"ja":"私はブラジルから来ました。","fu":"{私|わたし}はブラジルから{来|き}ました。","ru":"Я родом из Бразилии."}]},{"id":"kara-reason","pattern":"〜から（reason）","romaji":"kara (reason)","level":"N5","ru":"потому что; так как; поэтому","en":"because; since; so","formation":"Sentence + から","formationRu":"предложение + から","notes":"Сначала стоит причина: A から B (A, поэтому B). На вопрос どうして отвечают 〜からです. У существительных и прилагательных на -на нужно だ: 雨だから.","tags":["reason"],"ex":[{"ja":"今日は寒いから、コートを着ます。","fu":"{今日|きょう}は{寒|さむ}いから、コートを{着|き}ます。","ru":"Сегодня холодно, поэтому я надену пальто."},{"ja":"時間がありませんから、タクシーで行きましょう。","fu":"{時間|じかん}がありませんから、タクシーで{行|い}きましょう。","ru":"Времени нет, поэтому давайте поедем на такси."},{"ja":"「どうして休みましたか。」「頭が痛かったからです。」","fu":"「どうして{休|やす}みましたか。」「{頭|あたま}が{痛|いた}かったからです。」","ru":"«Почему вы не пришли?» — «Потому что у меня болела голова.»"}]},{"id":"ka-or","pattern":"〜か（or）","romaji":"ka (or)","level":"N5","ru":"или (выбор между существительными)","en":"or (a choice between nouns)","formation":"Noun + か + Noun","formationRu":"существительное + か + существительное","notes":"Означает, что выбирается один из названных предметов. Для перечисления предметов вместе берут と или や.","tags":["particle"],"ex":[{"ja":"飲み物はコーヒーか紅茶がいいです。","fu":"{飲|の}み{物|もの}はコーヒーか{紅茶|こうちゃ}がいいです。","ru":"Из напитков лучше кофе или чай."},{"ja":"土曜日か日曜日に買い物に行きます。","fu":"{土曜日|どようび}か{日曜日|にちようび}に{買|か}い{物|もの}に{行|い}きます。","ru":"Я пойду за покупками в субботу или воскресенье."},{"ja":"駅までバスかタクシーで行きます。","fu":"{駅|えき}までバスかタクシーで{行|い}きます。","ru":"До вокзала я поеду на автобусе или на такси."}]},{"id":"ka-question","pattern":"〜か（question）","romaji":"ka (question)","level":"N5","ru":"(вопросительная частица) превращает предложение в вопрос","en":"(question marker) turns a sentence into a question","formation":"Sentence + か","formationRu":"предложение + か","notes":"Вежливые вопросы кончаются на か и обычно записываются с точкой 。. В непринуждённой речи か чаще всего опускают, заменяя её восходящей интонацией.","tags":["particle","question"],"ex":[{"ja":"これはあなたのかばんですか。","fu":"これはあなたのかばんですか。","ru":"Это ваша сумка?"},{"ja":"朝ご飯を食べましたか。","fu":"{朝|あさ}ご{飯|はん}を{食|た}べましたか。","ru":"Вы позавтракали?"},{"ja":"トイレはどこですか。","fu":"トイレはどこですか。","ru":"Где находится туалет?"}]},{"id":"ga-aru-ga-iru","pattern":"〜がある / 〜がいる","romaji":"ga aru / ga iru","level":"N5","ru":"есть; имеются (ある для вещей, いる для людей и животных)","en":"there is; there are; have (ある for things, いる for people and animals)","formation":"Noun + がある / Noun + がいる","formationRu":"существительное + がある / существительное + がいる","notes":"ある — для вещей, растений и событий; いる — для людей и животных. Отрицательные формы: ない / いない (вежливо: ありません / いません).","tags":["state"],"ex":[{"ja":"公園に大きい木があります。","fu":"{公園|こうえん}に{大|おお}きい{木|き}があります。","ru":"В парке есть большое дерево."},{"ja":"私は妹が一人います。","fu":"{私|わたし}は{妹|いもうと}が{一人|ひとり}います。","ru":"У меня есть одна младшая сестра."},{"ja":"明日、日本語のテストがあります。","fu":"{明日|あした}、{日本語|にほんご}のテストがあります。","ru":"Завтра будет контрольная по японскому языку."}]},{"id":"ga-hoshii","pattern":"〜がほしい","romaji":"ga hoshii","level":"N5","ru":"хочется (чего-то)","en":"want (something)","formation":"Noun + がほしい","formationRu":"существительное + がほしい","notes":"Речь о вещах, а не о действиях (для действий — 〜たい). Изменяется как прилагательное на -い: ほしくない, ほしかった.","tags":["desire"],"ex":[{"ja":"新しいパソコンがほしいです。","fu":"{新|あたら}しいパソコンがほしいです。","ru":"Я хочу новый компьютер."},{"ja":"誕生日に何がほしいですか。","fu":"{誕生|たんじょう}{日|び}に{何|なに}がほしいですか。","ru":"Что вы хотите получить на день рождения?"},{"ja":"今は何もほしくないです。","fu":"{今|いま}は{何|なに}もほしくないです。","ru":"Сейчас я ничего не хочу."}]},{"id":"ga-jouzu-ga-heta","pattern":"〜が上手 / 〜が下手","romaji":"ga jouzu / ga heta","level":"N5","ru":"хорошо умеет (что-то); плохо умеет","en":"good at; bad at","formation":"Noun + が上手 / Noun + が下手","formationRu":"существительное + が上手 / существительное + が下手","notes":"Чаще говорят о других людях; о себе 上手 может прозвучать как хвастовство. Оба слова — прилагательные на -на: 料理が上手な人.","tags":["ability"],"ex":[{"ja":"姉はピアノが上手です。","fu":"{姉|あね}はピアノが{上手|じょうず}です。","ru":"Старшая сестра хорошо играет на пианино."},{"ja":"私は歌が下手です。","fu":"{私|わたし}は{歌|うた}が{下手|へた}です。","ru":"Я плохо пою."},{"ja":"マイクさんは日本語が上手ですね。","fu":"マイクさんは{日本語|にほんご}が{上手|じょうず}ですね。","ru":"Майк хорошо владеет японским, не правда ли?"}]},{"id":"ga-suki-ga-kirai","pattern":"〜が好き / 〜が嫌い","romaji":"ga suki / ga kirai","level":"N5","ru":"нравится; не нравится","en":"like; dislike","formation":"Noun + が好き / Noun + が嫌い / Verb-dict + の + が好き","formationRu":"существительное + が好き / существительное + が嫌い / глагол в словарной форме + の + が好き","notes":"好き и 嫌い — прилагательные на -на, поэтому то, что нравится, стоит с が, а не с を. 大好き и 大嫌い сильнее по смыслу. 嫌い может прозвучать резко; あまり好きじゃない мягче.","tags":["emotion"],"ex":[{"ja":"私は甘いものが好きです。","fu":"{私|わたし}は{甘|あま}いものが{好|す}きです。","ru":"Я люблю сладкое."},{"ja":"弟は野菜が嫌いです。","fu":"{弟|おとうと}は{野菜|やさい}が{嫌|きら}いです。","ru":"Младший брат не любит овощи."},{"ja":"母は料理をするのが好きです。","fu":"{母|はは}は{料理|りょうり}をするのが{好|す}きです。","ru":"Мама любит готовить."}]},{"id":"ga-but","pattern":"〜が（but）","romaji":"ga (but)","level":"N5","ru":"но; хотя","en":"but; although","formation":"Sentence + が","formationRu":"предложение + が","notes":"Используется и просто чтобы смягчить просьбу или перейти к теме: すみませんが…. Чуть официальнее, чем けど (N4).","tags":["contrast","particle"],"ex":[{"ja":"この店は安いですが、あまりおいしくないです。","fu":"この{店|みせ}は{安|やす}いですが、あまりおいしくないです。","ru":"В этом магазине недорого, но еда там не очень вкусная."},{"ja":"日本語は難しいですが、おもしろいです。","fu":"{日本語|にほんご}は{難|むずか}しいですが、おもしろいです。","ru":"Японский язык трудный, но интересный."},{"ja":"すみませんが、ちょっと静かにしてください。","fu":"すみませんが、ちょっと{静|しず}かにしてください。","ru":"Извините, прошу вас быть потише."}]},{"id":"ga-subject","pattern":"〜が（subject）","romaji":"ga (subject)","level":"N5","ru":"показывает подлежащее; выделяет новую или специально акцентируемую информацию","en":"marks the subject; points out new or focused information","formation":"Noun + が","formationRu":"существительное + が","notes":"Вопросительные слова, такие как だれ и 何, будучи подлежащим, берут が, а не は. Также が ставится при 好き, ほしい, 上手 и わかる — у того, что нравится, чего хочется или что понятно.","tags":["particle"],"ex":[{"ja":"雨が降っています。","fu":"{雨|あめ}が{降|ふ}っています。","ru":"Идёт дождь."},{"ja":"だれが窓を開けましたか。","fu":"だれが{窓|まど}を{開|あ}けましたか。","ru":"Кто открыл окно?"},{"ja":"私が行きます。","fu":"{私|わたし}が{行|い}きます。","ru":"Я пойду."}]},{"id":"kute-de","pattern":"〜くて / 〜で","romaji":"kute / de","level":"N5","ru":"и (соединяет прилагательные или существительные)","en":"and (linking adjectives or nouns)","formation":"i-Adj-ku + て / na-Adj + で / Noun + で","formationRu":"прилагательное на -い в форме -く + て / прилагательное на -на + で / существительное + で","notes":"いい даёт よくて. Соединяют качества, направленные в одну сторону (оба хорошие или оба плохие); для противопоставления берут が.","tags":["addition","conjugation"],"ex":[{"ja":"この店は安くておいしいです。","fu":"この{店|みせ}は{安|やす}くておいしいです。","ru":"В этом магазине дёшево и вкусно."},{"ja":"私の町は静かできれいです。","fu":"{私|わたし}の{町|まち}は{静|しず}かできれいです。","ru":"Мой город тихий и красивый."},{"ja":"兄は大学生で、妹は高校生です。","fu":"{兄|あに}は{大学生|だいがくせい}で、{妹|いもうと}は{高校生|こうこうせい}です。","ru":"Старший брат — студент университета, а младшая сестра — ученица старших классов."}]},{"id":"ku-nai-katta-ku-nakatta","pattern":"〜くない / 〜かった / 〜くなかった","romaji":"ku nai / katta / ku nakatta","level":"N5","ru":"отрицательные и прошедшие формы прилагательных на -い (не ...; был ...; не был ...)","en":"negative and past forms of i-adjectives (is not; was; was not)","formation":"i-Adj stem + くない / i-Adj stem + かった / i-Adj stem + くなかった","formationRu":"основа прилагательного на -い + くない / основа прилагательного на -い + かった / основа прилагательного на -い + くなかった","notes":"高い→高くない, 高かった, 高くなかった. Для вежливости добавляют です. いい — исключение: よくない, よかった, よくなかった.","tags":["conjugation","negation","tense"],"ex":[{"ja":"この部屋はあまり広くないです。","fu":"この{部屋|へや}はあまり{広|ひろ}くないです。","ru":"Эта комната не очень большая."},{"ja":"きのうのテストは難しかったです。","fu":"きのうのテストは{難|むずか}しかったです。","ru":"Вчерашняя контрольная была трудной."},{"ja":"先週見た映画はおもしろくなかったです。","fu":"{先週|せんしゅう}{見|み}た{映画|えいが}はおもしろくなかったです。","ru":"Фильм, который я смотрел на прошлой неделе, был неинтересным."}]},{"id":"ku-naru-ni-naru","pattern":"〜くなる / 〜になる","romaji":"ku naru / ni naru","level":"N5","ru":"стать; становиться; делаться","en":"become; get; turn","formation":"i-Adj-ku + なる / na-Adj + になる / Noun + になる","formationRu":"прилагательное на -い в форме -く + なる / прилагательное на -на + になる / существительное + になる","notes":"いい даёт よくなる. Часто в прошедшем времени описывают уже произошедшее изменение: 大きくなりました.","tags":["change"],"ex":[{"ja":"あたたかくなりましたね。","fu":"あたたかくなりましたね。","ru":"Стало тепло, не правда ли?"},{"ja":"部屋がきれいになりました。","fu":"{部屋|へや}がきれいになりました。","ru":"Комната стала чистой."},{"ja":"兄は来年、医者になります。","fu":"{兄|あに}は{来年|らいねん}、{医者|いしゃ}になります。","ru":"Старший брат в следующем году станет врачом."}]},{"id":"kurai-gurai","pattern":"〜くらい / 〜ぐらい（approximately）","romaji":"kurai / gurai","level":"N5","ru":"примерно; около (количества или длительности)","en":"about; approximately (an amount or length of time)","formation":"Noun + くらい / Noun + ぐらい","formationRu":"существительное + くらい / существительное + ぐらい","notes":"Употребляется с количеством и продолжительностью. Для момента времени (около трёх часов) берут ごろ: 3時ごろ.","tags":["quantity","degree"],"ex":[{"ja":"駅まで歩いて10分ぐらいです。","fu":"{駅|えき}まで{歩|ある}いて10{分|ぷん}ぐらいです。","ru":"До станции минут десять пешком."},{"ja":"毎日2時間くらい勉強します。","fu":"{毎日|まいにち}2{時間|じかん}くらい{勉強|べんきょう}します。","ru":"Каждый день я занимаюсь часа два."},{"ja":"このかばんは5000円ぐらいでした。","fu":"このかばんは5000{円|えん}ぐらいでした。","ru":"Эта сумка стоила около пяти тысяч иен."}]},{"id":"goro","pattern":"〜ごろ","romaji":"goro","level":"N5","ru":"около; примерно (о моменте времени)","en":"around; about (a point in time)","formation":"Noun + ごろ","formationRu":"существительное + ごろ","notes":"Присоединяется к часам, датам и месяцам. に после ごろ необязательна: 7時ごろ(に)起きます.","tags":["time"],"ex":[{"ja":"毎晩11時ごろ寝ます。","fu":"{毎晩|まいばん}11{時|じ}ごろ{寝|ね}ます。","ru":"Каждый вечер я ложусь спать около одиннадцати."},{"ja":"4月ごろ、桜が咲きます。","fu":"4{月|がつ}ごろ、{桜|さくら}が{咲|さ}きます。","ru":"Сакура зацветает примерно в апреле."},{"ja":"夕方6時ごろに家に帰ります。","fu":"{夕方|ゆうがた}6{時|じ}ごろに{家|いえ}に{帰|かえ}ります。","ru":"Я возвращаюсь домой около шести вечера."}]},{"id":"ta","pattern":"〜た","romaji":"ta","level":"N5","ru":"сделал (простое прошедшее время глагола)","en":"did (plain past of verbs)","formation":"Verb-ta","formationRu":"глагол в форме -た","notes":"Образуется совершенно так же, как форма て, только て→た и で→だ: 書いて→書いた, 飲んで→飲んだ, 行って→行った. Вежливый эквивалент: 〜ました.","tags":["conjugation","tense","casual"],"ex":[{"ja":"週末は家で映画を見た。","fu":"{週末|しゅうまつ}は{家|いえ}で{映画|えいが}を{見|み}た。","ru":"На выходных я смотрел дома фильм."},{"ja":"駅で先生に会った。","fu":"{駅|えき}で{先生|せんせい}に{会|あ}った。","ru":"На вокзале я встретил учителя."},{"ja":"「昼ご飯、食べた？」「うん、もう食べた。」","fu":"「{昼|ひる}ご{飯|はん}、{食|た}べた？」「うん、もう{食|た}べた。」","ru":"— Ты обедал? — Да, уже обедал."}]},{"id":"tai","pattern":"〜たい","romaji":"tai","level":"N5","ru":"хочу (сделать)","en":"want to (do)","formation":"Verb-stem + たい","formationRu":"основа масу-формы + たい","notes":"Изменяется как прилагательное на -い: 〜たくない, 〜たかった. У дополнения может стоять が или を. Для прямого высказывания желаний другого человека не употребляется.","tags":["desire"],"ex":[{"ja":"夏休みに沖縄へ行きたいです。","fu":"{夏休|なつやす}みに{沖縄|おきなわ}へ{行|い}きたいです。","ru":"На летних каникулах я хочу поехать на Окинаву."},{"ja":"冷たい水が飲みたいです。","fu":"{冷|つめ}たい{水|みず}が{飲|の}みたいです。","ru":"Хочется выпить холодной воды."},{"ja":"何が食べたいですか。","fu":"{何|なに}が{食|た}べたいですか。","ru":"Что бы вы хотели поесть?"}]},{"id":"ta-koto-ga-aru","pattern":"〜たことがある","romaji":"ta koto ga aru","level":"N5","ru":"когда-либо делал; иметь опыт (чего-либо)","en":"have (ever) done; have the experience of doing","formation":"Verb-ta + ことがある","formationRu":"глагол в форме -た + ことがある","notes":"Речь о жизненном опыте, а не о том, что только что сделали: きのう食べたことがある — ошибка. Отрицание 〜たことがありません значит «никогда не».","tags":["experience"],"ex":[{"ja":"富士山に登ったことがあります。","fu":"{富士山|ふじさん}に{登|のぼ}ったことがあります。","ru":"Я однажды поднимался на гору Фудзи."},{"ja":"日本の映画を見たことがありますか。","fu":"{日本|にほん}の{映画|えいが}を{見|み}たことがありますか。","ru":"Вы когда-нибудь смотрели японское кино?"},{"ja":"私は馬に乗ったことがありません。","fu":"{私|わたし}は{馬|うま}に{乗|の}ったことがありません。","ru":"Я никогда не катался на лошади."}]},{"id":"tari-tari-suru","pattern":"〜たり〜たりする","romaji":"tari ... tari suru","level":"N5","ru":"заниматься таким, как A и B; то A, то B","en":"do things like A and B; sometimes A, sometimes B","formation":"Verb-ta + り + Verb-ta + りする","formationRu":"глагол в форме -た + り + глагол в форме -た + りする","notes":"Выбирает лишь несколько действий из многих. Время и вежливость несёт конечное する: 〜たりしました.","tags":["example"],"ex":[{"ja":"日曜日はそうじをしたり、洗濯をしたりします。","fu":"{日曜日|にちようび}はそうじをしたり、{洗濯|せんたく}をしたりします。","ru":"По воскресеньям я делаю уборку, стираю и тому подобное."},{"ja":"休みの日は本を読んだり、音楽を聞いたりします。","fu":"{休|やす}みの{日|ひ}は{本|ほん}を{読|よ}んだり、{音楽|おんがく}を{聞|き}いたりします。","ru":"В выходные я читаю книги, слушаю музыку и тому подобное."},{"ja":"夏休みは海で泳いだり、山に登ったりしました。","fu":"{夏休|なつやす}みは{海|うみ}で{泳|およ}いだり、{山|やま}に{登|のぼ}ったりしました。","ru":"На летних каникулах я плавал в море, ходил в горы и тому подобное."}]},{"id":"da","pattern":"〜だ","romaji":"da","level":"N5","ru":"есть; является (простая связка «быть»)","en":"is; am; are (plain copula)","formation":"Noun + だ / na-Adj + だ","formationRu":"существительное + だ / прилагательное на -на + だ","notes":"Формы: だ, じゃない, だった, じゃなかった. Никогда не употребляется сразу после прилагательного на -い (高いだ — ошибка). В разговорных вопросах часто опускается: 学生？","tags":["copula","casual"],"ex":[{"ja":"今日は日曜日だ。","fu":"{今日|きょう}は{日曜日|にちようび}だ。","ru":"Сегодня воскресенье."},{"ja":"あの人は私の兄だ。","fu":"あの{人|ひと}は{私|わたし}の{兄|あに}だ。","ru":"Тот человек — мой старший брат."},{"ja":"明日は休みだから、ゆっくり寝る。","fu":"{明日|あした}は{休|やす}みだから、ゆっくり{寝|ね}る。","ru":"Завтра выходной, поэтому я посплю подольше."}]},{"id":"dake","pattern":"〜だけ","romaji":"dake","level":"N5","ru":"только; лишь","en":"only; just","formation":"Noun + だけ / Verb-dict + だけ","formationRu":"существительное + だけ / глагол в словарной форме + だけ","notes":"Нейтрально по тону. Сравните しか〜ない (N4), которое подчёркивает, что количество мало.","tags":["limitation"],"ex":[{"ja":"財布に100円だけあります。","fu":"{財布|さいふ}に100{円|えん}だけあります。","ru":"В кошельке всего сто иен."},{"ja":"朝はコーヒーだけ飲みます。","fu":"{朝|あさ}はコーヒーだけ{飲|の}みます。","ru":"Утром я пью только кофе."},{"ja":"日曜日だけ休みです。","fu":"{日曜日|にちようび}だけ{休|やす}みです。","ru":"Выходной только по воскресеньям."}]},{"id":"te","pattern":"〜て","romaji":"te","level":"N5","ru":"и; а затем (перечисление действий по порядку)","en":"and; and then (linking actions in order)","formation":"Verb-te + Sentence","formationRu":"глагол в форме -て + предложение","notes":"Время всему задаёт последний глагол. 書く→書いて, 飲む→飲んで, 話す→話して, 買う→買って, 行く→行って (исключение).","tags":["sequence"],"ex":[{"ja":"朝起きて、顔を洗います。","fu":"{朝|あさ}{起|お}きて、{顔|かお}を{洗|あら}います。","ru":"Утром я встаю и умываюсь."},{"ja":"デパートへ行って、セーターを買いました。","fu":"デパートへ{行|い}って、セーターを{買|か}いました。","ru":"Я пошёл в универмаг и купил свитер."},{"ja":"家に帰って、晩ご飯を食べて、寝ました。","fu":"{家|いえ}に{帰|かえ}って、{晩|ばん}ご{飯|はん}を{食|た}べて、{寝|ね}ました。","ru":"Я вернулся домой, поужинал и лёг спать."}]},{"id":"te-iru","pattern":"〜ている","romaji":"te iru","level":"N5","ru":"делать сейчас (длящееся действие); находиться в состоянии (результат изменения); делать регулярно","en":"be doing (ongoing action); be in a state (result of a change); do regularly","formation":"Verb-te + いる","formationRu":"глагол в форме -て + いる","notes":"С глаголами действия (食べる, 読む) показывает действие в процессе; с глаголами изменения (結婚する, 開く, 知る) — достигнутый результат. Вежливо: 〜ています.","tags":["state"],"ex":[{"ja":"弟は今、部屋でゲームをしています。","fu":"{弟|おとうと}は{今|いま}、{部屋|へや}でゲームをしています。","ru":"Младший брат сейчас у себя в комнате играет в игру."},{"ja":"姉は結婚しています。","fu":"{姉|あね}は{結婚|けっこん}しています。","ru":"Старшая сестра замужем."},{"ja":"窓が開いています。","fu":"{窓|まど}が{開|あ}いています。","ru":"Окно открыто."}]},{"id":"te-kara","pattern":"〜てから","romaji":"te kara","level":"N5","ru":"после того как сделал; сделав A, затем B; с тех пор как","en":"after doing; (do A) and then (B); since","formation":"Verb-te + から","formationRu":"глагол в форме -て + から","notes":"Подчёркивает, что A полностью завершено до начала B, яснее, чем простая форма て. С ている в главном предложении часто значит «с тех пор как».","tags":["sequence","time"],"ex":[{"ja":"手を洗ってから、ご飯を食べましょう。","fu":"{手|て}を{洗|あら}ってから、ご{飯|はん}を{食|た}べましょう。","ru":"Давайте сначала помоем руки, а потом будем есть."},{"ja":"宿題をしてから、テレビを見ます。","fu":"{宿題|しゅくだい}をしてから、テレビを{見|み}ます。","ru":"Сначала я сделаю домашнее задание, а потом посмотрю телевизор."},{"ja":"日本に来てから、毎日日本語を勉強しています。","fu":"{日本|にほん}に{来|き}てから、{毎日|まいにち}{日本語|にほんご}を{勉強|べんきょう}しています。","ru":"С тех пор как я приехал в Японию, я занимаюсь японским языком каждый день."}]},{"id":"te-kudasai","pattern":"〜てください","romaji":"te kudasai","level":"N5","ru":"пожалуйста, сделайте (что-то)","en":"please (do)","formation":"Verb-te + ください","formationRu":"глагол в форме -て + ください","notes":"Вежливо, но всё же это указание, которое, как ждут, будет выполнено. Более мягкие просьбы — 〜てくれませんか (N4).","tags":["request","politeness"],"ex":[{"ja":"もう少しゆっくり話してください。","fu":"もう{少|すこ}しゆっくり{話|はな}してください。","ru":"Говорите, пожалуйста, чуть помедленнее."},{"ja":"ここでくつをぬいでください。","fu":"ここでくつをぬいでください。","ru":"Пожалуйста, снимите здесь обувь."},{"ja":"すみません、駅までの道を教えてください。","fu":"すみません、{駅|えき}までの{道|みち}を{教|おし}えてください。","ru":"Извините, подскажите, пожалуйста, как дойти до вокзала."}]},{"id":"te-wa-ikenai","pattern":"〜てはいけない","romaji":"te wa ikenai","level":"N5","ru":"нельзя; не разрешается","en":"must not; may not","formation":"Verb-te + はいけない","formationRu":"глагол в форме -て + はいけない","notes":"Сильный запрет, чаще о правилах. Вежливая форма: 〜てはいけません. Разговорное сокращение: 〜ちゃいけない / 〜じゃいけない.","tags":["prohibition"],"ex":[{"ja":"図書館で大きい声で話してはいけません。","fu":"{図書館|としょかん}で{大|おお}きい{声|こえ}で{話|はな}してはいけません。","ru":"В библиотеке нельзя разговаривать громко."},{"ja":"子どもはこの川で泳いではいけません。","fu":"{子|こ}どもはこの{川|かわ}で{泳|およ}いではいけません。","ru":"Детям нельзя плавать в этой реке."},{"ja":"ここでたばこを吸ってはいけません。","fu":"ここでたばこを{吸|す}ってはいけません。","ru":"Здесь нельзя курить."}]},{"id":"te-mo-ii","pattern":"〜てもいい","romaji":"te mo ii","level":"N5","ru":"можно; разрешается","en":"may; it's okay to","formation":"Verb-te + もいい","formationRu":"глагол в форме -て + もいい","notes":"Чтобы попросить разрешения, добавляют ですか. Вежливый отказ часто звучит просто как すみません、ちょっと…","tags":["permission"],"ex":[{"ja":"この辞書を使ってもいいですか。","fu":"この{辞書|じしょ}を{使|つか}ってもいいですか。","ru":"Можно мне воспользоваться этим словарём?"},{"ja":"今日は早く帰ってもいいです。","fu":"{今日|きょう}は{早|はや}く{帰|かえ}ってもいいです。","ru":"Сегодня можно уйти домой пораньше."},{"ja":"ここにすわってもいいですか。","fu":"ここにすわってもいいですか。","ru":"Можно я сяду здесь?"}]},{"id":"deshita","pattern":"〜でした","romaji":"deshita","level":"N5","ru":"был; были (вежливая связка в прошедшем времени)","en":"was; were (polite past copula)","formation":"Noun + でした / na-Adj + でした","formationRu":"существительное + でした / прилагательное на -на + でした","notes":"Отрицание прошедшего: ではありませんでした. Прилагательные на -い не присоединяют でした: говорят 高かったです, а не 高いでした.","tags":["copula","tense","politeness"],"ex":[{"ja":"きのうは私の誕生日でした。","fu":"きのうは{私|わたし}の{誕生|たんじょう}{日|び}でした。","ru":"Вчера был мой день рождения."},{"ja":"子どものころ、野菜がきらいでした。","fu":"{子|こ}どものころ、{野菜|やさい}がきらいでした。","ru":"В детстве я не любил овощи."},{"ja":"テストはかんたんでした。","fu":"テストはかんたんでした。","ru":"Тест был лёгкий."}]},{"id":"deshou","pattern":"〜でしょう","romaji":"deshou","level":"N5","ru":"вероятно; по-видимому; ..., не так ли?","en":"probably; I think; ..., right?","formation":"Verb-plain / i-Adj / na-Adj / Noun + でしょう","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + でしょう","notes":"Типично для прогнозов погоды. С восходящей интонацией это просьба к слушателю согласиться. Простая форма: だろう (N4).","tags":["conjecture"],"ex":[{"ja":"明日は雨が降るでしょう。","fu":"{明日|あした}は{雨|あめ}が{降|ふ}るでしょう。","ru":"Завтра, вероятно, пойдёт дождь."},{"ja":"山の上は寒いでしょう。","fu":"{山|やま}の{上|うえ}は{寒|さむ}いでしょう。","ru":"На горе, наверное, холодно."},{"ja":"このかばん、かわいいでしょう？","fu":"このかばん、かわいいでしょう？","ru":"Эта сумка ведь симпатичная, правда?"}]},{"id":"desu","pattern":"〜です","romaji":"desu","level":"N5","ru":"есть; является (вежливая связка «быть»)","en":"is; am; are (polite copula)","formation":"Noun + です / na-Adj + です / i-Adj + です","formationRu":"существительное + です / прилагательное на -на + です / прилагательное на -い + です","notes":"Формы: です, ではありません, でした, ではありませんでした. После прилагательного на -い です добавляет только вежливость: 高いです.","tags":["copula","politeness"],"ex":[{"ja":"私はマリアです。","fu":"{私|わたし}はマリアです。","ru":"Я Мария."},{"ja":"今日は月曜日です。","fu":"{今日|きょう}は{月曜日|げつようび}です。","ru":"Сегодня понедельник."},{"ja":"この部屋はとても静かです。","fu":"この{部屋|へや}はとても{静|しず}かです。","ru":"Эта комната очень тихая."}]},{"id":"de-wa-arimasen-ja-nai","pattern":"〜ではありません / 〜じゃない","romaji":"de wa arimasen / ja nai","level":"N5","ru":"не есть; не является (отрицание связки)","en":"is not; am not; are not","formation":"Noun + ではありません / na-Adj + ではありません / Noun + じゃない / na-Adj + じゃない","formationRu":"существительное + ではありません / прилагательное на -на + ではありません / существительное + じゃない / прилагательное на -на + じゃない","notes":"じゃありません и じゃないです — более разговорные вежливые формы. Прошедшее время: ではありませんでした / じゃなかった. У прилагательных на -и вместо этого используется 〜くない.","tags":["copula","negation"],"ex":[{"ja":"私は先生ではありません。学生です。","fu":"{私|わたし}は{先生|せんせい}ではありません。{学生|がくせい}です。","ru":"Я не учитель, я студент."},{"ja":"今日は休みじゃない。","fu":"{今日|きょう}は{休|やす}みじゃない。","ru":"Сегодня не выходной."},{"ja":"この町はあまりにぎやかではありません。","fu":"この{町|まち}はあまりにぎやかではありません。","ru":"Этот город не очень оживлённый."}]},{"id":"de-means","pattern":"〜で（means）","romaji":"de (means)","level":"N5","ru":"посредством; на; при помощи (средство, инструмент, способ или язык)","en":"by; with; in (means, tool, method or language)","formation":"Noun + で","formationRu":"существительное + で","notes":"Чтобы сказать «пешком», употребляют 歩いて行きます, а не частицу で.","tags":["particle","means"],"ex":[{"ja":"毎日電車で会社へ行きます。","fu":"{毎日|まいにち}{電車|でんしゃ}で{会社|かいしゃ}へ{行|い}きます。","ru":"Каждый день я езжу на работу на поезде."},{"ja":"はしでご飯を食べます。","fu":"はしでご{飯|はん}を{食|た}べます。","ru":"Я ем рис палочками для еды."},{"ja":"日本語で手紙を書きました。","fu":"{日本語|にほんご}で{手紙|てがみ}を{書|か}きました。","ru":"Я написал письмо на японском языке."}]},{"id":"de-place","pattern":"〜で（place of action）","romaji":"de (place)","level":"N5","ru":"в; на (место, где происходит действие)","en":"at; in (the place where an action happens)","formation":"Noun + で","formationRu":"существительное + で","notes":"Сравните 教室にいます (находиться где-то — に) и 教室で勉強します (делать что-то там — で).","tags":["particle"],"ex":[{"ja":"図書館で本を読みます。","fu":"{図書館|としょかん}で{本|ほん}を{読|よ}みます。","ru":"В библиотеке я читаю книги."},{"ja":"きのう、デパートでくつを買いました。","fu":"きのう、デパートでくつを{買|か}いました。","ru":"Вчера я купил туфли в универмаге."},{"ja":"駅の前で友達を待ちました。","fu":"{駅|えき}の{前|まえ}で{友達|ともだち}を{待|ま}ちました。","ru":"Я подождал друга перед вокзалом."}]},{"id":"to-to-dochira-ga","pattern":"〜と〜とどちらが","romaji":"to ... to dochira ga","level":"N5","ru":"что более ..., X или Y?","en":"which is more ..., X or Y?","formation":"Noun + と + Noun + とどちらが","formationRu":"существительное + と + существительное + とどちらが","notes":"Сравнивает ровно два предмета. どっち — разговорный вариант どちら. Отвечают конструкцией 〜の方が.","tags":["comparison","question"],"ex":[{"ja":"コーヒーと紅茶とどちらが好きですか。","fu":"コーヒーと{紅茶|こうちゃ}とどちらが{好|す}きですか。","ru":"Что вам больше нравится: кофе или чай?"},{"ja":"電車とバスとどちらが安いですか。","fu":"{電車|でんしゃ}とバスとどちらが{安|やす}いですか。","ru":"Что дешевле: поезд или автобус?"},{"ja":"「山と海とどちらがいいですか。」「海の方がいいです。」","fu":"「{山|やま}と{海|うみ}とどちらがいいですか。」「{海|うみ}の{方|ほう}がいいです。」","ru":"— Что лучше: горы или море? — Лучше море."}]},{"id":"to-iu-named","pattern":"〜という（named）","romaji":"to iu (named)","level":"N5","ru":"называемый; по имени","en":"called; named","formation":"Noun + という + Noun","formationRu":"существительное + という + существительное","notes":"Представляет имя, которое слушателю может быть неизвестно.","tags":["quotation"],"ex":[{"ja":"これは「すきやき」という料理です。","fu":"これは「すきやき」という{料理|りょうり}です。","ru":"Это блюдо называется «сукияки»."},{"ja":"「さくら」という店でアルバイトをしています。","fu":"「さくら」という{店|みせ}でアルバイトをしています。","ru":"Я подрабатываю в магазине под названием «Сакура»."},{"ja":"山田さんという人から電話がありました。","fu":"{山田|やまだ}さんという{人|ひと}から{電話|でんわ}がありました。","ru":"Звонил некий Ямада."}]},{"id":"to-and","pattern":"〜と（and）","romaji":"to (and)","level":"N5","ru":"и (соединяет существительные в полном перечне)","en":"and (joining nouns in a complete list)","formation":"Noun + と + Noun","formationRu":"существительное + と + существительное","notes":"と перечисляет все предметы; чтобы привести только несколько примеров, берут や. Соединяет только существительные, но не глаголы и не прилагательные.","tags":["particle","addition"],"ex":[{"ja":"かばんの中にペンとノートがあります。","fu":"かばんの{中|なか}にペンとノートがあります。","ru":"В сумке лежат ручка и тетрадь."},{"ja":"朝ご飯にパンとたまごを食べました。","fu":"{朝|あさ}ご{飯|はん}にパンとたまごを{食|た}べました。","ru":"На завтрак я ел хлеб и яйца."},{"ja":"父と母は銀行で働いています。","fu":"{父|ちち}と{母|はは}は{銀行|ぎんこう}で{働|はたら}いています。","ru":"Папа и мама работают в банке."}]},{"id":"to-with","pattern":"〜と（with）","romaji":"to (with)","level":"N5","ru":"с; вместе с (партнёр по действию)","en":"with; together with (a partner in an action)","formation":"Noun + と","formationRu":"существительное + と","notes":"Часто рядом стоит いっしょに. С глаголами вроде 話す, 会う и 結婚する показывает другого человека.","tags":["particle"],"ex":[{"ja":"週末、友達と映画を見ました。","fu":"{週末|しゅうまつ}、{友達|ともだち}と{映画|えいが}を{見|み}ました。","ru":"На выходных я смотрел фильм с другом."},{"ja":"妹といっしょに買い物に行きます。","fu":"{妹|いもうと}といっしょに{買|か}い{物|もの}に{行|い}きます。","ru":"Я иду за покупками вместе с младшей сестрой."},{"ja":"だれと昼ご飯を食べましたか。","fu":"だれと{昼|ひる}ご{飯|はん}を{食|た}べましたか。","ru":"С кем вы обедали?"}]},{"id":"nai","pattern":"〜ない","romaji":"nai","level":"N5","ru":"не делаю; не буду (простое отрицание глагола)","en":"do not; will not (plain negative of verbs)","formation":"Verb-nai stem + ない","formationRu":"основа формы -ない + ない","notes":"У глаголов на -у последний звук -u меняется на -a: 書く→書かない, 買う→買わない. У глаголов на -る отбрасывается る: 食べない. する→しない, 来る→こない, ある→ない. Прошедшее время: 〜なかった.","tags":["conjugation","negation","casual"],"ex":[{"ja":"今日は学校へ行かない。","fu":"{今日|きょう}は{学校|がっこう}へ{行|い}かない。","ru":"Сегодня я не пойду в школу."},{"ja":"兄は肉を食べない。","fu":"{兄|あに}は{肉|にく}を{食|た}べない。","ru":"Мой старший брат не ест мясо."},{"ja":"「コーヒー、飲む？」「ううん、飲まない。」","fu":"「コーヒー、{飲|の}む？」「ううん、{飲|の}まない。」","ru":"— Будешь кофе? — Нет, не буду."}]},{"id":"naide-kudasai","pattern":"〜ないでください","romaji":"naide kudasai","level":"N5","ru":"пожалуйста, не делайте (чего-то)","en":"please don't (do)","formation":"Verb-nai + でください","formationRu":"глагол в форме -ない + でください","notes":"Мягче, чем 〜てはいけません. В непринуждённой речи ください опускают: 見ないで.","tags":["request","prohibition"],"ex":[{"ja":"教室で食べないでください。","fu":"{教室|きょうしつ}で{食|た}べないでください。","ru":"Пожалуйста, не ешьте в классе."},{"ja":"この部屋に入らないでください。","fu":"この{部屋|へや}に{入|はい}らないでください。","ru":"Пожалуйста, не входите в эту комнату."},{"ja":"心配しないでください。","fu":"{心配|しんぱい}しないでください。","ru":"Пожалуйста, не волнуйтесь."}]},{"id":"nagara","pattern":"〜ながら（while）","romaji":"nagara","level":"N5","ru":"делая (два действия одновременно); в то время как","en":"while (doing two actions at the same time)","formation":"Verb-stem + ながら","formationRu":"основа масу-формы + ながら","notes":"Оба действия выполняет один и тот же человек. Главное действие стоит последним: в A-ながら B главным является B.","tags":["simultaneity"],"ex":[{"ja":"音楽を聞きながら勉強します。","fu":"{音楽|おんがく}を{聞|き}きながら{勉強|べんきょう}します。","ru":"Я занимаюсь, слушая музыку."},{"ja":"父はいつも新聞を読みながら朝ご飯を食べます。","fu":"{父|ちち}はいつも{新聞|しんぶん}を{読|よ}みながら{朝|あさ}ご{飯|はん}を{食|た}べます。","ru":"Отец всегда завтракает, читая газету."},{"ja":"コーヒーを飲みながら話しましょう。","fu":"コーヒーを{飲|の}みながら{話|はな}しましょう。","ru":"Давайте поговорим за чашкой кофе."}]},{"id":"nakute-mo-ii","pattern":"〜なくてもいい","romaji":"nakute mo ii","level":"N5","ru":"не нужно; не обязательно","en":"don't have to; need not","formation":"Verb-nai stem + なくてもいい","formationRu":"основа формы -ない + なくてもいい","notes":"Противоположность 〜なければならない. Вопрос задают так: 〜なくてもいいですか (Можно не ...?).","tags":["necessity","permission"],"ex":[{"ja":"明日は学校へ来なくてもいいです。","fu":"{明日|あした}は{学校|がっこう}へ{来|こ}なくてもいいです。","ru":"Завтра можно не приходить в школу."},{"ja":"名前は書かなくてもいいです。","fu":"{名前|なまえ}は{書|か}かなくてもいいです。","ru":"Имя можно не писать."},{"ja":"今日は料理をしなくてもいいですよ。","fu":"{今日|きょう}は{料理|りょうり}をしなくてもいいですよ。","ru":"Сегодня не обязательно готовить."}]},{"id":"nakereba-naranai-nakute-wa-ikenai","pattern":"〜なければならない / 〜なくてはいけない","romaji":"nakereba naranai / nakute wa ikenai","level":"N5","ru":"должен; надо; необходимо","en":"must; have to","formation":"Verb-nai stem + なければならない / Verb-nai stem + なくてはいけない","formationRu":"основа формы -ない + なければならない / основа формы -ない + なくてはいけない","notes":"Вежливые варианты кончаются на なりません / いけません. Оба значат одно и то же; なりなければならない звучит чуть более официально.","tags":["obligation"],"ex":[{"ja":"明日は6時に起きなければなりません。","fu":"{明日|あした}は6{時|じ}に{起|お}きなければなりません。","ru":"Завтра мне нужно встать в 6 часов."},{"ja":"今日は早く家に帰らなくてはいけません。","fu":"{今日|きょう}は{早|はや}く{家|いえ}に{帰|かえ}らなくてはいけません。","ru":"Сегодня нужно пораньше вернуться домой."},{"ja":"日本では、家に入る前にくつをぬがなければなりません。","fu":"{日本|にほん}では、{家|いえ}に{入|はい}る{前|まえ}にくつをぬがなければなりません。","ru":"В Японии перед входом в дом нужно снять обувь."}]},{"id":"na-na-adjective","pattern":"〜な（na-adjective）","romaji":"na (na-adjective)","level":"N5","ru":"прилагательные на -на: перед существительным берут な, в конце предложения — です или だ","en":"na-adjectives: take な before a noun and です or だ at the end of a sentence","formation":"na-Adj + な + Noun / na-Adj + です / na-Adj + ではありません / na-Adj + でした","formationRu":"прилагательное на -на + な + существительное / прилагательное на -на + です / прилагательное на -на + ではありません / прилагательное на -на + でした","notes":"Перед существительным добавляется な: 静かな部屋. В конце предложения изменяются, как существительные. きれい и きらい оканчиваются на い, но относятся к прилагательным на -на.","tags":["conjugation"],"ex":[{"ja":"京都は有名な町です。","fu":"{京都|きょうと}は{有名|ゆうめい}な{町|まち}です。","ru":"Киото — известный город."},{"ja":"きのうは暇でした。","fu":"きのうは{暇|ひま}でした。","ru":"Вчера у меня было много свободного времени."},{"ja":"この部屋はあまり静かではありません。","fu":"この{部屋|へや}はあまり{静|しず}かではありません。","ru":"В этой комнате не очень тихо."}]},{"id":"ni-suru","pattern":"〜にする（decide）","romaji":"ni suru","level":"N5","ru":"решить выбрать; выбрать; мне (это)","en":"decide on; choose; I'll have","formation":"Noun + にする","formationRu":"существительное + にする","notes":"Часто при заказе еды или при выборе из нескольких вариантов. Прошедшее время: 〜にしました (я выбрал ...).","tags":["decision"],"ex":[{"ja":"私はカレーにします。","fu":"{私|わたし}はカレーにします。","ru":"Я возьму карри."},{"ja":"飲み物は何にしますか。","fu":"{飲|の}み{物|もの}は{何|なに}にしますか。","ru":"Что вы будете пить?"},{"ja":"旅行は来月にしましょう。","fu":"{旅行|りょこう}は{来月|らいげつ}にしましょう。","ru":"Давайте перенесём поездку на следующий месяц."}]},{"id":"ni-iku","pattern":"〜に行く","romaji":"ni iku","level":"N5","ru":"идти (куда-то), чтобы сделать что-то","en":"go (somewhere) to do","formation":"Verb-stem + に行く / Noun + に行く","formationRu":"основа масу-формы + に行く / существительное + に行く","notes":"Так же работают 来る и 帰る: 遊びに来る. С существительными на -する слово может стоять напрямую: 買い物に行く, 散歩に行く.","tags":["purpose"],"ex":[{"ja":"デパートへ服を買いに行きます。","fu":"デパートへ{服|ふく}を{買|か}いに{行|い}きます。","ru":"Я иду в универмаг за одеждой."},{"ja":"週末、海へ泳ぎに行きました。","fu":"{週末|しゅうまつ}、{海|うみ}へ{泳|およ}ぎに{行|い}きました。","ru":"На выходных я ездил на море купаться."},{"ja":"友達がうちへ遊びに来ました。","fu":"{友達|ともだち}がうちへ{遊|あそ}びに{来|き}ました。","ru":"Ко мне домой пришёл друг поиграть."}]},{"id":"ni-destination","pattern":"〜に（destination）","romaji":"ni (destination)","level":"N5","ru":"в; на (пункт назначения движения)","en":"to; into (the destination of movement)","formation":"Noun + に + 行く / 来る / 帰る","formationRu":"существительное + に + 行く / 来る / 帰る","notes":"Близко по смыслу к へ. に делает упор на пункте прибытия, へ — на направлении.","tags":["particle"],"ex":[{"ja":"毎日バスで学校に行きます。","fu":"{毎日|まいにち}バスで{学校|がっこう}に{行|い}きます。","ru":"Каждый день я езжу в школу на автобусе."},{"ja":"夜10時に家に帰りました。","fu":"{夜|よる}10{時|じ}に{家|いえ}に{帰|かえ}りました。","ru":"Я вернулся домой в десять часов вечера."},{"ja":"来月、姉が日本に来ます。","fu":"{来月|らいげつ}、{姉|あね}が{日本|にほん}に{来|き}ます。","ru":"В следующем месяце старшая сестра приедет в Японию."}]},{"id":"ni-frequency","pattern":"〜に（frequency）","romaji":"ni (frequency)","level":"N5","ru":"в; за (сколько раз за какой-то период)","en":"per; in (how many times within a period)","formation":"Noun + に + Noun","formationRu":"существительное + に + существительное","notes":"Сначала идёт период, затем に, затем число раз: 月に一回 (один раз в месяц).","tags":["particle","quantity"],"ex":[{"ja":"一週間に二回、プールで泳ぎます。","fu":"{一週間|いっしゅうかん}に{二|に}{回|かい}、プールで{泳|およ}ぎます。","ru":"Два раза в неделю я плаваю в бассейне."},{"ja":"母は一日に二回、犬の散歩をします。","fu":"{母|はは}は{一|いち}{日|にち}に{二|に}{回|かい}、{犬|いぬ}の{散歩|さんぽ}をします。","ru":"Мама два раза в день гуляет с собакой."},{"ja":"一年に一度、家族で旅行します。","fu":"{一|いち}{年|ねん}に{一|いち}{度|ど}、{家族|かぞく}で{旅行|りょこう}します。","ru":"Раз в год мы всей семьёй ездим в путешествие."}]},{"id":"ni-indirect-object","pattern":"〜に（indirect object）","romaji":"ni (indirect object)","level":"N5","ru":"кому (человеку, который получает что-то или кому адресовано действие)","en":"to (the person who receives or is the target of an action)","formation":"Noun + に","formationRu":"существительное + に","notes":"Часто с あげる, 貸す, 教える, 見せる, 電話をかける и 会う. При もらう и 借りる に показывает человека, у которого что-то получают.","tags":["particle"],"ex":[{"ja":"母に手紙を書きます。","fu":"{母|はは}に{手紙|てがみ}を{書|か}きます。","ru":"Я пишу письмо матери."},{"ja":"妹に本を貸しました。","fu":"{妹|いもうと}に{本|ほん}を{貸|か}しました。","ru":"Я одолжил книгу младшей сестре."},{"ja":"友達に電話をかけました。","fu":"{友達|ともだち}に{電話|でんわ}をかけました。","ru":"Я позвонил другу."}]},{"id":"ni-location","pattern":"〜に（place of existence）","romaji":"ni (location)","level":"N5","ru":"в; на (там, где кто-то или что-то находится)","en":"in; at; on (where someone or something is)","formation":"Noun + に + ある / いる","formationRu":"существительное + に + ある / いる","notes":"Употребляется с ある, いる и 住む. Для места, где происходит действие (есть, учиться, играть), вместо него берётся で.","tags":["particle"],"ex":[{"ja":"机の上に辞書があります。","fu":"{机|つくえ}の{上|うえ}に{辞書|じしょ}があります。","ru":"На столе лежит словарь."},{"ja":"姉は東京に住んでいます。","fu":"{姉|あね}は{東京|とうきょう}に{住|す}んでいます。","ru":"Старшая сестра живёт в Токио."},{"ja":"猫は今どこにいますか。","fu":"{猫|ねこ}は{今|いま}どこにいますか。","ru":"Где сейчас кошка?"}]},{"id":"ni-time","pattern":"〜に（time）","romaji":"ni (time)","level":"N5","ru":"в; на (о определённом моменте времени)","en":"at; on; in (a specific point in time)","formation":"Noun + に","formationRu":"существительное + に","notes":"Употребляется с часами, датами, днями недели и месяцами. С относительными словами, такими как 今日, 明日, 毎日 и 来週, частица に не ставится.","tags":["particle","time"],"ex":[{"ja":"毎朝7時に起きます。","fu":"{毎朝|まいあさ}7{時|じ}に{起|お}きます。","ru":"Каждое утро я встаю в семь часов."},{"ja":"日曜日に友達と会います。","fu":"{日曜日|にちようび}に{友達|ともだち}と{会|あ}います。","ru":"В воскресенье я встречусь с другом."},{"ja":"8月に国へ帰ります。","fu":"8{月|がつ}に{国|くに}へ{帰|かえ}ります。","ru":"В августе я вернусь на родину."}]},{"id":"ne","pattern":"〜ね","romaji":"ne","level":"N5","ru":"не так ли?; верно? (поиск согласия, разделение чувства)","en":"isn't it?; right? (seeking agreement or sharing a feeling)","formation":"Sentence + ね","formationRu":"предложение + ね","notes":"Употребляется, когда говорящий ожидает, что слушатель разделяет ту же точку зрения или знает то же самое. Сравните よ, которое сообщает слушателю что-то новое.","tags":["particle"],"ex":[{"ja":"今日は暑いですね。","fu":"{今日|きょう}は{暑|あつ}いですね。","ru":"Сегодня жарко, правда?"},{"ja":"このケーキ、おいしいですね。","fu":"このケーキ、おいしいですね。","ru":"Этот торт очень вкусный, правда?"},{"ja":"明日のテストは10時からですね。","fu":"{明日|あした}のテストは10{時|じ}からですね。","ru":"Завтрашний тест начинается в 10 часов, верно?"}]},{"id":"no-naka-de-ga-ichiban","pattern":"〜の中で〜が一番","romaji":"no naka de ... ga ichiban","level":"N5","ru":"самый ... среди / из (чего-либо)","en":"... is the most ... among/of","formation":"Noun + の中で + Noun + が一番","formationRu":"существительное + の中で + существительное + が一番","notes":"Употребляется при трёх и более предметах. В вопросе перед が一番 ставят 何, だれ, どこ или いつ.","tags":["comparison","range"],"ex":[{"ja":"果物の中でりんごが一番好きです。","fu":"{果物|くだもの}の{中|なか}でりんごが{一番|いちばん}{好|す}きです。","ru":"Из всех фруктов я больше всего люблю яблоки."},{"ja":"クラスの中でだれが一番背が高いですか。","fu":"クラスの{中|なか}でだれが{一番|いちばん}{背|せ}が{高|たか}いですか。","ru":"Кто в классе самый высокий?"},{"ja":"家族の中で父が一番早く起きます。","fu":"{家族|かぞく}の{中|なか}で{父|ちち}が{一番|いちばん}{早|はや}く{起|お}きます。","ru":"В нашей семье папа встаёт раньше всех."}]},{"id":"no-hou-ga-yori","pattern":"〜の方が〜より","romaji":"no hou ga ... yori","level":"N5","ru":"X более ..., чем Y","en":"X is more ... than Y","formation":"Noun + の方が + Noun + より","formationRu":"существительное + の方が + существительное + より","notes":"Обе части могут стоять в любом порядке. Часто служит для ответа на вопрос с どちら.","tags":["comparison"],"ex":[{"ja":"犬の方が猫より好きです。","fu":"{犬|いぬ}の{方|ほう}が{猫|ねこ}より{好|す}きです。","ru":"Собаки мне нравятся больше, чем кошки."},{"ja":"東京の方が大阪より人が多いです。","fu":"{東京|とうきょう}の{方|ほう}が{大阪|おおさか}より{人|ひと}が{多|おお}いです。","ru":"В Токио жителей больше, чем в Осаке."},{"ja":"夏より冬の方が好きです。","fu":"{夏|なつ}より{冬|ふゆ}の{方|ほう}が{好|す}きです。","ru":"Зима мне нравится больше, чем лето."}]},{"id":"no","pattern":"〜の（possessive）","romaji":"no","level":"N5","ru":"принадлежность (аналог родительного падежа); из; описательная связь двух существительных","en":"'s; of (possession, belonging or description)","formation":"Noun + の + Noun","formationRu":"существительное + の + существительное","notes":"Первое существительное характеризует второе: 日本の車 (японская машина). Когда смысл ясен, второе существительное можно опустить: それは私のです.","tags":["particle"],"ex":[{"ja":"これは私のかさです。","fu":"これは{私|わたし}のかさです。","ru":"Это мой зонт."},{"ja":"日本語の先生はとてもやさしいです。","fu":"{日本語|にほんご}の{先生|せんせい}はとてもやさしいです。","ru":"Учитель японского языка очень добрый."},{"ja":"駅の近くに新しい店があります。","fu":"{駅|えき}の{近|ちか}くに{新|あたら}しい{店|みせ}があります。","ru":"Рядом с вокзалом есть новый магазин."}]},{"id":"wa","pattern":"〜は","romaji":"wa","level":"N5","ru":"что касается; показывает тему (о чём) предложения","en":"as for; marks the topic of the sentence","formation":"Noun + は","formationRu":"существительное + は","notes":"Пишется は, но читается «wa». Частица задаёт то, о чём идёт речь в предложении; самая важная информация идёт после неё.","tags":["particle","topic"],"ex":[{"ja":"私は学生です。","fu":"{私|わたし}は{学生|がくせい}です。","ru":"Я студент."},{"ja":"今日は天気がいいです。","fu":"{今日|きょう}は{天気|てんき}がいいです。","ru":"Сегодня хорошая погода."},{"ja":"この本はおもしろいです。","fu":"この{本|ほん}はおもしろいです。","ru":"Эта книга интересная."}]},{"id":"e","pattern":"〜へ","romaji":"e","level":"N5","ru":"в; по направлению к (направление движения)","en":"to; toward (the direction of movement)","formation":"Noun + へ","formationRu":"существительное + へ","notes":"Пишется へ, но читается «e». Для пунктов назначения обычно взаимозаменяемо с に; へ чуть сильнее подчёркивает направление.","tags":["particle"],"ex":[{"ja":"夏休みに北海道へ行きます。","fu":"{夏休|なつやす}みに{北海道|ほっかいどう}へ{行|い}きます。","ru":"На летних каникулах я поеду на Хоккайдо."},{"ja":"来週、国へ帰ります。","fu":"{来週|らいしゅう}、{国|くに}へ{帰|かえ}ります。","ru":"На следующей неделе я вернусь на родину."},{"ja":"どこへ行きますか。","fu":"どこへ{行|い}きますか。","ru":"Куда вы идёте?"}]},{"id":"mashita","pattern":"〜ました","romaji":"mashita","level":"N5","ru":"сделал; делал (вежливое прошедшее время)","en":"did (polite past)","formation":"Verb-stem + ました","formationRu":"основа масу-формы + ました","notes":"Простой эквивалент — форма на た: 会いました = 会った.","tags":["conjugation","tense","politeness"],"ex":[{"ja":"きのう、友達に会いました。","fu":"きのう、{友達|ともだち}に{会|あ}いました。","ru":"Вчера я встретил друга."},{"ja":"先週、新しいくつを買いました。","fu":"{先週|せんしゅう}、{新|あたら}しいくつを{買|か}いました。","ru":"На прошлой неделе я купил новую обувь."},{"ja":"けさ、6時に起きました。","fu":"けさ、6{時|じ}に{起|お}きました。","ru":"Сегодня утром я встал в 6 часов."}]},{"id":"mashou","pattern":"〜ましょう","romaji":"mashou","level":"N5","ru":"давайте (сделаем)","en":"let's (do)","formation":"Verb-stem + ましょう","formationRu":"основа масу-формы + ましょう","notes":"Употребляется, когда говорящий ожидает согласия слушателя. Чтобы пригласить мягче, используйте 〜ませんか.","tags":["invitation","suggestion"],"ex":[{"ja":"いっしょに行きましょう。","fu":"いっしょに{行|い}きましょう。","ru":"Пойдём вместе."},{"ja":"少し休みましょう。","fu":"{少|すこ}し{休|やす}みましょう。","ru":"Давайте немного отдохнём."},{"ja":"駅の前で会いましょう。","fu":"{駅|えき}の{前|まえ}で{会|あ}いましょう。","ru":"Встретимся перед вокзалом."}]},{"id":"mashou-ka","pattern":"〜ましょうか","romaji":"mashou ka","level":"N5","ru":"мне ...?; давай ...?","en":"shall I ...?; shall we ...?","formation":"Verb-stem + ましょうか","formationRu":"основа масу-формы + ましょうか","notes":"Предлагает сделать что-то для слушателя («мне?») или просит решить что-то вместе («давай?»).","tags":["suggestion","invitation"],"ex":[{"ja":"窓を開けましょうか。","fu":"{窓|まど}を{開|あ}けましょうか。","ru":"Мне открыть окно?"},{"ja":"荷物を持ちましょうか。","fu":"{荷物|にもつ}を{持|も}ちましょうか。","ru":"Помочь вам донести вещи?"},{"ja":"何時に会いましょうか。","fu":"{何|なん}{時|じ}に{会|あ}いましょうか。","ru":"Во сколько нам встретиться?"}]},{"id":"masu","pattern":"〜ます","romaji":"masu","level":"N5","ru":"вежливое непрошедшее окончание глагола (делаю; сделаю)","en":"polite non-past verb ending (do; will do)","formation":"Verb-stem + ます","formationRu":"основа масу-формы + ます","notes":"Охватывает привычные действия и будущие. 飲む→飲みます, 食べる→食べます, する→します, 来る→来ます.","tags":["conjugation","politeness"],"ex":[{"ja":"毎朝コーヒーを飲みます。","fu":"{毎朝|まいあさ}コーヒーを{飲|の}みます。","ru":"Каждое утро я пью кофе."},{"ja":"明日、京都へ行きます。","fu":"{明日|あした}、{京都|きょうと}へ{行|い}きます。","ru":"Завтра я поеду в Киото."},{"ja":"弟は毎晩9時に寝ます。","fu":"{弟|おとうと}は{毎晩|まいばん}9{時|じ}に{寝|ね}ます。","ru":"Мой младший брат каждый вечер ложится спать в 9 часов."}]},{"id":"masen","pattern":"〜ません","romaji":"masen","level":"N5","ru":"не делаю; не буду (вежливое отрицание)","en":"do not; will not (polite negative)","formation":"Verb-stem + ません","formationRu":"основа масу-формы + ません","notes":"Простой (невежливый) эквивалент — форма на ない: 飲みません = 飲まない.","tags":["conjugation","negation","politeness"],"ex":[{"ja":"私はお酒を飲みません。","fu":"{私|わたし}はお{酒|さけ}を{飲|の}みません。","ru":"Я не пью алкоголь."},{"ja":"日曜日は学校へ行きません。","fu":"{日曜日|にちようび}は{学校|がっこう}へ{行|い}きません。","ru":"В воскресенье я не хожу в школу."},{"ja":"今晩はテレビを見ません。","fu":"{今晩|こんばん}はテレビを{見|み}ません。","ru":"Сегодня вечером я не буду смотреть телевизор."}]},{"id":"masen-ka","pattern":"〜ませんか","romaji":"masen ka","level":"N5","ru":"не хотите ли ...?; хотели бы вы ...? (вежливое приглашение)","en":"won't you ...?; would you like to ...? (polite invitation)","formation":"Verb-stem + ませんか","formationRu":"основа масу-формы + ませんか","notes":"Мягче, чем 〜ましょう, потому что оставляет слушателю возможность отказаться. Согласие выражают: ええ、〜ましょう.","tags":["invitation"],"ex":[{"ja":"いっしょに昼ご飯を食べませんか。","fu":"いっしょに{昼|ひる}ご{飯|はん}を{食|た}べませんか。","ru":"Не хотите пообедать вместе?"},{"ja":"日曜日にテニスをしませんか。","fu":"{日曜日|にちようび}にテニスをしませんか。","ru":"Не хотите сыграть в теннис в воскресенье?"},{"ja":"明日、公園を散歩しませんか。","fu":"{明日|あした}、{公園|こうえん}を{散歩|さんぽ}しませんか。","ru":"Может, завтра погуляем в парке?"}]},{"id":"masen-deshita","pattern":"〜ませんでした","romaji":"masen deshita","level":"N5","ru":"не сделал (вежливое отрицание в прошедшем времени)","en":"did not (polite past negative)","formation":"Verb-stem + ませんでした","formationRu":"основа масу-формы + ませんでした","notes":"Простой эквивалент — 〜なかった: 食べませんでした = 食べなかった.","tags":["conjugation","tense","negation"],"ex":[{"ja":"けさは朝ご飯を食べませんでした。","fu":"けさは{朝|あさ}ご{飯|はん}を{食|た}べませんでした。","ru":"Сегодня утром я не завтракал."},{"ja":"週末は宿題をしませんでした。","fu":"{週末|しゅうまつ}は{宿題|しゅくだい}をしませんでした。","ru":"На выходных я не делал домашнее задание."},{"ja":"きのうは雨でしたから、出かけませんでした。","fu":"きのうは{雨|あめ}でしたから、{出|で}かけませんでした。","ru":"Вчера был дождь, поэтому я не выходил из дома."}]},{"id":"made","pattern":"〜まで（until）","romaji":"made","level":"N5","ru":"до; вплоть до; до самого","en":"until; up to; as far as","formation":"Noun + まで","formationRu":"существительное + まで","notes":"Показывает конечную точку чего-то продолжающегося. Для срока («к определённому времени») употребляется までに (N4).","tags":["particle","time","range"],"ex":[{"ja":"昼休みは1時までです。","fu":"{昼休|ひるやす}みは1{時|じ}までです。","ru":"Обеденный перерыв — до 1 часа."},{"ja":"駅までいっしょに行きましょう。","fu":"{駅|えき}までいっしょに{行|い}きましょう。","ru":"Давайте пойдём вместе до вокзала."},{"ja":"きのうは夜11時まで勉強しました。","fu":"きのうは{夜|よる}11{時|じ}まで{勉強|べんきょう}しました。","ru":"Вчера я занимался до 11 часов вечера."}]},{"id":"mo","pattern":"〜も","romaji":"mo","level":"N5","ru":"тоже; тоже; (при отрицании) тоже не...; ни... ни","en":"also; too; (with a negative) not ... either; neither ... nor","formation":"Noun + も","formationRu":"существительное + も","notes":"も заменяет собой は, が и を, но после других частиц ставится после них: 京都にも行きました.","tags":["particle","addition"],"ex":[{"ja":"私も学生です。","fu":"{私|わたし}も{学生|がくせい}です。","ru":"Я тоже студент."},{"ja":"兄はサッカーも好きです。","fu":"{兄|あに}はサッカーも{好|す}きです。","ru":"Мой старший брат тоже любит футбол."},{"ja":"肉も魚も食べません。","fu":"{肉|にく}も{魚|さかな}も{食|た}べません。","ru":"Я не ем ни мяса, ни рыбы."}]},{"id":"ya","pattern":"〜や","romaji":"ya","level":"N5","ru":"и (перечисляет лишь часть из многих); ... и так далее","en":"and (giving some examples out of more); ... and so on","formation":"Noun + や + Noun","formationRu":"существительное + や + существительное","notes":"Подразумевается, что перечень неполный. Часто завершается словом など: 本や雑誌など.","tags":["particle","example"],"ex":[{"ja":"机の上に本や雑誌があります。","fu":"{机|つくえ}の{上|うえ}に{本|ほん}や{雑誌|ざっし}があります。","ru":"На столе лежат книги, журналы и так далее."},{"ja":"スーパーで肉や野菜を買いました。","fu":"スーパーで{肉|にく}や{野菜|やさい}を{買|か}いました。","ru":"В супермаркете я купил мясо, овощи и прочее."}]},{"id":"yo","pattern":"〜よ","romaji":"yo","level":"N5","ru":"знайте; говорю вам (сообщение новой информации или подчёркивание)","en":"you know; I tell you (giving new information or emphasis)","formation":"Sentence + よ","formationRu":"предложение + よ","notes":"Сообщает слушателю то, чего он, возможно, не знает. По отношению к старшим чрезмерное употребление может прозвучать навязчиво.","tags":["particle","emphasis"],"ex":[{"ja":"このラーメンはとてもおいしいですよ。","fu":"このラーメンはとてもおいしいですよ。","ru":"Знаете, этот рамен очень вкусный."},{"ja":"かさを忘れていますよ。","fu":"かさを{忘|わす}れていますよ。","ru":"Вы ведь забыли зонт."},{"ja":"明日はテストがありますよ。","fu":"{明日|あした}はテストがありますよ。","ru":"Завтра будет тест, не забудьте."}]},{"id":"yori","pattern":"〜より","romaji":"yori","level":"N5","ru":"чем (точка сравнения)","en":"than (the standard of comparison)","formation":"Noun + より","formationRu":"существительное + より","notes":"В конструкции X は Y より + прилагательное Y является точкой сравнения. В японском у прилагательных нет формы сравнительной степени («-ее»); эту роль выполняет より.","tags":["particle","comparison"],"ex":[{"ja":"今日はきのうより寒いです。","fu":"{今日|きょう}はきのうより{寒|さむ}いです。","ru":"Сегодня холоднее, чем вчера."},{"ja":"電車はバスより速いです。","fu":"{電車|でんしゃ}はバスより{速|はや}いです。","ru":"Поезд быстрее, чем автобус."},{"ja":"兄は父より背が高いです。","fu":"{兄|あに}は{父|ちち}より{背|せ}が{高|たか}いです。","ru":"Мой старший брат выше отца."}]},{"id":"o","pattern":"〜を","romaji":"o","level":"N5","ru":"показывает прямое дополнение глагола; показывает место, по которому движутся или которое покидают","en":"marks the direct object of a verb; marks a place moved through or left","formation":"Noun + を","formationRu":"существительное + を","notes":"Пишется を, но читается «o». С глаголами движения, такими как 歩く, 散歩する и 出る, показывает маршрут или место, которое оставляют.","tags":["particle"],"ex":[{"ja":"毎朝パンを食べます。","fu":"{毎朝|まいあさ}パンを{食|た}べます。","ru":"Каждое утро я ем хлеб."},{"ja":"姉は新しいかばんを買いました。","fu":"{姉|あね}は{新|あたら}しいかばんを{買|か}いました。","ru":"Старшая сестра купила новую сумку."},{"ja":"公園を散歩しました。","fu":"{公園|こうえん}を{散歩|さんぽ}しました。","ru":"Я погулял в парке."}]},{"id":"o-kudasai","pattern":"〜をください","romaji":"o kudasai","level":"N5","ru":"дайте, пожалуйста (что-то); мне, пожалуйста","en":"please give me (something); I'll have","formation":"Noun + をください","formationRu":"существительное + をください","notes":"Употребляется при покупках и в заказе. Количество стоит после を без частицы: 切手を二枚ください.","tags":["request"],"ex":[{"ja":"すみません、水をください。","fu":"すみません、{水|みず}をください。","ru":"Извините, дайте мне, пожалуйста, воды."},{"ja":"このりんごを三つください。","fu":"このりんごを{三|みっ}つください。","ru":"Дайте мне, пожалуйста, три этих яблока."},{"ja":"メニューをください。","fu":"メニューをください。","ru":"Дайте, пожалуйста, меню."}]},{"id":"mae-ni","pattern":"〜前に","romaji":"mae ni","level":"N5","ru":"прежде чем (сделать); перед (событием); назад","en":"before (doing); before (an event); ago","formation":"Verb-dict + 前に / Noun + の + 前に","formationRu":"глагол в словарной форме + 前に / существительное + の + 前に","notes":"Глагол перед 前に всегда стоит в словарной форме, даже когда речь о прошлом. С длительностью времени の не ставится: 3年前に (три года назад).","tags":["time","sequence"],"ex":[{"ja":"寝る前に歯をみがきます。","fu":"{寝|ね}る{前|まえ}に{歯|は}をみがきます。","ru":"Перед сном я чищу зубы."},{"ja":"授業の前にコーヒーを飲みます。","fu":"{授業|じゅぎょう}の{前|まえ}にコーヒーを{飲|の}みます。","ru":"Перед уроком я пью кофе."},{"ja":"3年前に日本へ来ました。","fu":"3{年|ねん}{前|まえ}に{日本|にほん}へ{来|き}ました。","ru":"Я приехал в Японию три года назад."}]},{"id":"ato-de","pattern":"〜後で","romaji":"ato de","level":"N5","ru":"после того как (сделал); после (события)","en":"after (doing); after (an event)","formation":"Verb-ta + 後で / Noun + の + 後で","formationRu":"глагол в форме -た + 後で / существительное + の + 後で","notes":"Глагол перед 後で всегда стоит в форме た, даже когда речь о будущих планах. Отдельно 後で значит «позже, потом».","tags":["time","sequence"],"ex":[{"ja":"晩ご飯を食べた後で、散歩をします。","fu":"{晩|ばん}ご{飯|はん}を{食|た}べた{後|あと}で、{散歩|さんぽ}をします。","ru":"После ужина я иду гулять."},{"ja":"仕事の後で、いっしょに飲みに行きませんか。","fu":"{仕事|しごと}の{後|あと}で、いっしょに{飲|の}みに{行|い}きませんか。","ru":"Может, после работы пойдём вместе выпить?"},{"ja":"テストが終わった後で、友達と遊びました。","fu":"テストが{終|お}わった{後|あと}で、{友達|ともだち}と{遊|あそ}びました。","ru":"После того как контрольная закончилась, я погулял с друзьями."}]},{"id":"amari-nai","pattern":"あまり〜ない","romaji":"amari ... nai","level":"N5","ru":"не очень; не особенно; не часто","en":"not very; not much; not often","formation":"あまり + Verb-nai / あまり + i-Adj-ku + ない / あまり + na-Adj + じゃない","formationRu":"あまり + глагол в форме -ない / あまり + прилагательное на -い в форме -く + ない / あまり + прилагательное на -на + じゃない","notes":"Всегда сочетается с отрицанием. あまり好きじゃない — мягкий способ сказать, что что-то не нравится.","tags":["negation","degree"],"ex":[{"ja":"私はあまりテレビを見ません。","fu":"{私|わたし}はあまりテレビを{見|み}ません。","ru":"Я не слишком много смотрю телевизор."},{"ja":"このりんごはあまり甘くないです。","fu":"このりんごはあまり{甘|あま}くないです。","ru":"Это яблоко не очень сладкое."},{"ja":"今日はあまり忙しくありません。","fu":"{今日|きょう}はあまり{忙|いそが}しくありません。","ru":"Сегодня я не слишком занят."}]},{"id":"koko-soko-asoko-doko","pattern":"ここ / そこ / あそこ / どこ","romaji":"koko / soko / asoko / doko","level":"N5","ru":"здесь; там (рядом с вами); вон там; где","en":"here; there (near you); over there; where","formation":"ここ / そこ / あそこ / どこ","formationRu":"ここ / そこ / あそこ / どこ","notes":"こちら / そちら / あちら / どちら — более вежливые варианты: お国はどちらですか (Откуда вы?).","tags":["demonstrative"],"ex":[{"ja":"ここは私の学校です。","fu":"ここは{私|わたし}の{学校|がっこう}です。","ru":"Здесь моя школа."},{"ja":"トイレはあそこです。","fu":"トイレはあそこです。","ru":"Туалет — вон там."},{"ja":"すみません、駅はどこですか。","fu":"すみません、{駅|えき}はどこですか。","ru":"Скажите, пожалуйста, где находится станция?"}]},{"id":"kono-sono-ano-dono","pattern":"この / その / あの / どの","romaji":"kono / sono / ano / dono","level":"N5","ru":"этот; тот (рядом с вами); тот вон тот; какой (перед существительным)","en":"this; that (near you); that ... over there; which (before a noun)","formation":"この / その / あの / どの + Noun","formationRu":"この / その / あの / どの + существительное","notes":"Всегда стоят перед существительным: この本, само по себе この не употребляется. Если существительного нет, берут これ / それ / あれ / どれ.","tags":["demonstrative"],"ex":[{"ja":"このケーキはおいしいです。","fu":"このケーキはおいしいです。","ru":"Этот торт очень вкусный."},{"ja":"その本はだれのですか。","fu":"その{本|ほん}はだれのですか。","ru":"Чья это книга?"},{"ja":"「どの人が先生ですか。」「あの人です。」","fu":"「どの{人|ひと}が{先生|せんせい}ですか。」「あの{人|ひと}です。」","ru":"«Кто из этих людей учитель?» — «Вон тот.»"}]},{"id":"kore-sore-are-dore","pattern":"これ / それ / あれ / どれ","romaji":"kore / sore / are / dore","level":"N5","ru":"это; это (рядом с вами); то (вон там); какое? / который?","en":"this one; that one (near you); that one (over there); which one","formation":"これ / それ / あれ / どれ","formationRu":"これ / それ / あれ / どれ","notes":"こ — около говорящего, そ — около слушателя, あ — вдали от обоих, ど — вопрос. Употребляются самостоятельно; в роли подлежащего どれ берёт が, а не は.","tags":["demonstrative"],"ex":[{"ja":"これは私の辞書です。","fu":"これは{私|わたし}の{辞書|じしょ}です。","ru":"Это мой словарь."},{"ja":"それは何ですか。","fu":"それは{何|なに}ですか。","ru":"Что это?"},{"ja":"「あなたのかさはどれですか。」「あれです。」","fu":"「あなたのかさはどれですか。」「あれです。」","ru":"«Который зонтик ваш?» — «Вон тот.»"}]},{"id":"mada-te-inai","pattern":"まだ〜ていない","romaji":"mada ... te inai","level":"N5","ru":"ещё не (сделал)","en":"not yet (have done)","formation":"まだ + Verb-te + いない / まだ + Verb-te + いません","formationRu":"まだ + глагол в форме -て + いない / まだ + глагол в форме -て + いません","notes":"О том, что ещё может произойти, говорят через ていない, а не через ませんでした. Краткий ответ: いいえ、まだです.","tags":["negation","completion"],"ex":[{"ja":"まだ昼ご飯を食べていません。","fu":"まだ{昼|ひる}ご{飯|はん}を{食|た}べていません。","ru":"Я ещё не обедал."},{"ja":"「宿題はもうしましたか。」「いいえ、まだしていません。」","fu":"「{宿題|しゅくだい}はもうしましたか。」「いいえ、まだしていません。」","ru":"«Вы уже сделали домашнее задание?» — «Нет, ещё не сделал.»"},{"ja":"電車はまだ来ていません。","fu":"{電車|でんしゃ}はまだ{来|き}ていません。","ru":"Поезд ещё не пришёл."}]},{"id":"mou-ta","pattern":"もう〜た","romaji":"mou ... ta","level":"N5","ru":"уже (сделал); (в вопросе) уже?","en":"already (have done); (in questions) yet","formation":"もう + Verb-ta / もう + Verb-stem + ました","formationRu":"もう + глагол в форме -た / もう + основа масу-формы + ました","notes":"В вопросе もう значит «уже?». С отрицательным глаголом もう значит «больше не»: もう食べません.","tags":["completion","time"],"ex":[{"ja":"「もう晩ご飯を食べましたか。」「はい、もう食べました。」","fu":"「もう{晩|ばん}ご{飯|はん}を{食|た}べましたか。」「はい、もう{食|た}べました。」","ru":"«Вы уже поужинали?» — «Да, уже.»"},{"ja":"妹はもう寝ました。","fu":"{妹|いもうと}はもう{寝|ね}ました。","ru":"Младшая сестра уже легла спать."},{"ja":"映画はもう始まりましたよ。","fu":"{映画|えいが}はもう{始|はじ}まりましたよ。","ru":"Фильм уже начался."}]},{"id":"nani-ka-dare-ka-doko-ka","pattern":"何か / 誰か / どこか","romaji":"nani ka / dare ka / doko ka","level":"N5","ru":"что-то; кто-то; где-то","en":"something; someone; somewhere","formation":"Question word + か","formationRu":"вопросительное слово + か","notes":"Вопросительное слово + か даёт слова типа «некий-»; вопросительное слово + も + отрицание даёт слова типа «никакой-». После 何か / だれか частицы が и を часто опускают.","tags":["question"],"ex":[{"ja":"何か飲みますか。","fu":"{何|なに}か{飲|の}みますか。","ru":"Будете что-нибудь пить?"},{"ja":"だれか来ましたよ。","fu":"だれか{来|き}ましたよ。","ru":"Кто-то приходил."},{"ja":"夏休みにどこかへ行きましたか。","fu":"{夏休|なつやす}みにどこかへ{行|い}きましたか。","ru":"Вы куда-нибудь ездили на летних каникулах?"}]},{"id":"nani-mo-nai-dare-mo-nai","pattern":"何も〜ない / 誰も〜ない","romaji":"nani mo ... nai / dare mo ... nai","level":"N5","ru":"ничего; никто; ничто","en":"nothing; nobody; not anything; not anyone","formation":"何も + Verb-nai / 誰も + Verb-nai","formationRu":"何も + глагол в форме -ない / 誰も + глагол в форме -ない","notes":"С указанием места частица стоит перед も: どこにも / どこへも行きません (никуда не идти). 誰 часто пишут хираганой: だれ.","tags":["negation"],"ex":[{"ja":"けさは何も食べませんでした。","fu":"けさは{何|なに}も{食|た}べませんでした。","ru":"Сегодня утром я ничего не ел."},{"ja":"教室にはだれもいません。","fu":"{教室|きょうしつ}にはだれもいません。","ru":"В классе никого нет."},{"ja":"冷蔵庫の中には何もありません。","fu":"{冷蔵庫|れいぞうこ}の{中|なか}には{何|なに}もありません。","ru":"В холодильнике ничего нет."}]},{"id":"zenzen-nai","pattern":"全然〜ない","romaji":"zenzen ... nai","level":"N5","ru":"нисколько; совсем не; отнюдь","en":"not at all; not in the least","formation":"全然 + Verb-nai / 全然 + i-Adj-ku + ない / 全然 + na-Adj + じゃない","formationRu":"全然 + глагол в форме -ない / 全然 + прилагательное на -い в форме -く + ない / 全然 + прилагательное на -на + じゃない","notes":"Сильнее, чем あまり〜ない. В разговорной речи 全然 иногда употребляют и с утверждением (全然大丈夫), но норма — сочетание с отрицанием.","tags":["negation","degree"],"ex":[{"ja":"この問題は全然わかりません。","fu":"この{問題|もんだい}は{全然|ぜんぜん}わかりません。","ru":"Эту задачу я совсем не понимаю."},{"ja":"今日は全然寒くないです。","fu":"{今日|きょう}は{全然|ぜんぜん}{寒|さむ}くないです。","ru":"Сегодня совсем не холодно."},{"ja":"弟は全然勉強しません。","fu":"{弟|おとうと}は{全然|ぜんぜん}{勉強|べんきょう}しません。","ru":"Младший брат совсем не занимается."}]},{"id":"you-to-omou","pattern":"〜(よ)うと思う","romaji":"you to omou","level":"N4","ru":"подумываю сделать; собираюсь","en":"be thinking of doing; plan to","formation":"Verb-volitional + と思う","formationRu":"волевительная форма (-у/-よう) + と思う","notes":"〜と思う часто сообщает о решении, принятом только что; 〜と思っている — о плане, который вы держите уже какое-то время. Мягче, чем つもり.","tags":["intention"],"ex":[{"ja":"今年の夏は海に行こうと思っています。","fu":"{今年|ことし}の{夏|なつ}は{海|うみ}に{行|い}こうと{思|おも}っています。","ru":"Этим летом я думаю поехать к морю."},{"ja":"明日は早く起きて、公園を走ろうと思う。","fu":"{明日|あした}は{早|はや}く{起|お}きて、{公園|こうえん}を{走|はし}ろうと{思|おも}う。","ru":"Завтра я хочу встать пораньше и побегать в парке."},{"ja":"新しいパソコンを買おうと思ったけど、やめました。","fu":"{新|あたら}しいパソコンを{買|か}おうと{思|おも}ったけど、やめました。","ru":"Я было хотел купить новый компьютер, но передумал."}]},{"id":"e-ro","pattern":"〜え / 〜ろ","romaji":"e / ro","level":"N4","ru":"сделай! (повелительная форма; резкая команда)","en":"do it! (imperative form; blunt command)","formation":"Verb-dict (Group 1: final u → e) / Verb-stem + ろ (Group 2)","formationRu":"глагол в словарной форме (1-я группа: конечное u → e) / основа масу-формы + ろ (2-я группа)","notes":"Неправильные: する → しろ, 来る → 来い, くれる → くれ. Очень резко; чаще у мужчин, на табличках, в экстренных ситуациях и в кричалках (がんばれ).","tags":["command","conjugation"],"ex":[{"ja":"早く起きろ！遅刻するぞ。","fu":"{早|はや}く{起|お}きろ！{遅刻|ちこく}するぞ。","ru":"Быстро вставай! А то опоздаем!"},{"ja":"危ない！止まれ！","fu":"{危|あぶ}ない！{止|と}まれ！","ru":"Осторожно! Стой!"},{"ja":"がんばれ！あと少しだ！","fu":"がんばれ！あと{少|すこ}しだ！","ru":"Не сдавайся! Осталось совсем немного!"}]},{"id":"eru-rareru-potential","pattern":"〜える / 〜られる（potential）","romaji":"eru / rareru (potential)","level":"N4","ru":"мочь; быть в состоянии (потенциальная форма)","en":"can; be able to (potential form)","formation":"Verb-dict (Group 1: final u → e) + る / Verb-nai stem + られる (Group 2)","formationRu":"глагол в словарной форме (1-я группа: конечное u → e) + る / основа формы -ない + られる (2-я группа)","notes":"Неправильные: する → できる, 来る → 来られる. Дополнение часто берёт が вместо を. В разговорной речи у глаголов 2-й группы часто опускают ら (見れる).","tags":["ability","conjugation"],"ex":[{"ja":"私は漢字が二百ぐらい読めます。","fu":"{私|わたし}は{漢字|かんじ}が{二|に}{百|ひゃく}ぐらい{読|よ}めます。","ru":"Я могу прочитать примерно двести иероглифов."},{"ja":"兄は辛い料理が食べられない。","fu":"{兄|あに}は{辛|から}い{料理|りょうり}が{食|た}べられない。","ru":"Старший брат не может есть острую пищу."},{"ja":"明日のパーティーに来られますか。","fu":"{明日|あした}のパーティーに{来|こ}られますか。","ru":"Сможете прийти на завтрашнюю вечеринку?"}]},{"id":"ou-you","pattern":"〜おう / 〜よう","romaji":"ou / you","level":"N4","ru":"давай(те) (разговорное); я сделаю (волевительная форма)","en":"let's (casual); I'll (volitional form)","formation":"Verb-dict (Group 1: final u → o) + う / Verb-stem + よう (Group 2)","formationRu":"глагол в словарной форме (1-я группа: конечное u → o) + う / основа масу-формы + よう (2-я группа)","notes":"Неправильные: する → しよう, 来る → 来よう. Простой эквивалент 〜ましょう.","tags":["conjugation","invitation","intention"],"ex":[{"ja":"疲れたね。少し休もう。","fu":"{疲|つか}れたね。{少|すこ}し{休|やす}もう。","ru":"Устал, правда? Давай немного отдохнём."},{"ja":"週末、一緒に映画を見ようよ。","fu":"{週末|しゅうまつ}、{一緒|いっしょ}に{映画|えいが}を{見|み}ようよ。","ru":"Давай на выходных вместе посмотрим фильм."},{"ja":"よし、今日から毎日日記を書こう。","fu":"よし、{今日|きょう}から{毎日|まいにち}{日記|にっき}を{書|か}こう。","ru":"Ладно, с сегодняшнего дня буду каждый день вести дневник."}]},{"id":"oki-ni","pattern":"〜おきに","romaji":"oki ni","level":"N4","ru":"через один; с интервалом в","en":"every other; at intervals of","formation":"Noun (number + counter) + おきに","formationRu":"существительное (число + счётное слово) + おきに","notes":"С днями (一日おき) пропускается одна единица, то есть «через день». С минутами и расстояниями обычно означает просто «каждые X».","tags":["time","quantity"],"ex":[{"ja":"このバスは十五分おきに来ます。","fu":"このバスは{十|じゅう}{五|ご}{分|ふん}おきに{来|き}ます。","ru":"Этот автобус ходит каждые пятнадцать минут."},{"ja":"一日おきにジョギングをしています。","fu":"{一|いち}{日|にち}おきにジョギングをしています。","ru":"Я бегаю через день."},{"ja":"道の両側に、木が五メートルおきに植えてある。","fu":"{道|みち}の{両側|りょうがわ}に、{木|き}が{五|ご}メートルおきに{植|う}えてある。","ru":"По обеим сторонам дороги деревья посажены через каждые пять метров."}]},{"id":"ka-dou-ka","pattern":"〜かどうか","romaji":"ka dou ka","level":"N4","ru":"или нет","en":"whether or not","formation":"Verb-plain / i-Adj / na-Adj / Noun + かどうか","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + かどうか","notes":"Встраивает вопрос «да или нет» в предложение. В вопросах с вопросительным словом используется просто 〜か (何時に来るか).","tags":["question"],"ex":[{"ja":"明日行けるかどうか、まだ分かりません。","fu":"{明日|あした}{行|い}けるかどうか、まだ{分|わ}かりません。","ru":"Смогу ли я пойти завтра, пока ещё неизвестно."},{"ja":"この服が似合うかどうか、ちょっと着てみます。","fu":"この{服|ふく}が{似合|にあ}うかどうか、ちょっと{着|き}てみます。","ru":"Надену эту одежду и посмотрю, идёт ли она мне."},{"ja":"そのレストランがおいしいかどうか、友達に聞いてみよう。","fu":"そのレストランがおいしいかどうか、{友達|ともだち}に{聞|き}いてみよう。","ru":"Спрошу у друзей, вкусно ли в том ресторане."}]},{"id":"kana-kashira","pattern":"〜かな / 〜かしら","romaji":"kana / kashira","level":"N4","ru":"интересно; хотелось бы знать","en":"I wonder","formation":"Verb-plain / i-Adj / na-Adj / Noun + かな / かしら","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + かな / かしら","notes":"Мягкий вопрос, часто сказанный самому себе. かしら звучит по-женски и чуть старомодно. 〜ないかな может выражать желание (早く来ないかな).","tags":["question","casual"],"ex":[{"ja":"明日は晴れるかな。","fu":"{明日|あした}は{晴|は}れるかな。","ru":"Интересно, завтра будет ясно?"},{"ja":"このお菓子、誰が買ってきたのかな。","fu":"このお{菓子|かし}、{誰|だれ}が{買|か}ってきたのかな。","ru":"Интересно, кто купил эти сладости?"},{"ja":"この服、私に似合うかしら。","fu":"この{服|ふく}、{私|わたし}に{似合|にあ}うかしら。","ru":"Интересно, пойдёт ли мне эта одежда?"}]},{"id":"kamo-shirenai","pattern":"〜かもしれない","romaji":"kamo shirenai","level":"N4","ru":"возможно; может быть; наверное","en":"might; may; possibly","formation":"Verb-plain / i-Adj / na-Adj / Noun + かもしれない","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + かもしれない","notes":"Уверенность примерно на 50 % и ниже. В разговорной речи часто сокращается до かも.","tags":["possibility","conjecture"],"ex":[{"ja":"午後から雨が降るかもしれません。","fu":"{午後|ごご}から{雨|あめ}が{降|ふ}るかもしれません。","ru":"Во второй половине дня, возможно, пойдёт дождь."},{"ja":"かぎがない。電車の中で落としたかもしれない。","fu":"かぎがない。{電車|でんしゃ}の{中|なか}で{落|お}としたかもしれない。","ru":"Ключа нет. Возможно, я обронил его в поезде."},{"ja":"その話は本当かもしれない。","fu":"その{話|はなし}は{本当|ほんとう}かもしれない。","ru":"Эта история, возможно, правда."}]},{"id":"ka-embedded-question","pattern":"〜か（embedded question）","romaji":"ka (embedded question)","level":"N4","ru":"встроенный вопрос (что, где, кто и т. п.)","en":"embedded question (what, where, who, etc.)","formation":"Question word + ... + Verb-plain / i-Adj / na-Adj / Noun + か","formationRu":"вопросительное слово + ... + простая форма / прилагательное на -い / прилагательное на -на / существительное + か","notes":"После существительного или на-прилагательного だ опускается (誰の傘か知らない).","tags":["question"],"ex":[{"ja":"会議が何時に始まるか、教えてください。","fu":"{会議|かいぎ}が{何|なん}{時|じ}に{始|はじ}まるか、{教|おし}えてください。","ru":"Скажите, во сколько начинается совещание."},{"ja":"どこで財布をなくしたか、覚えていません。","fu":"どこで{財布|さいふ}をなくしたか、{覚|おぼ}えていません。","ru":"Я не помню, где потерял кошелёк."},{"ja":"誰が窓を割ったか、知っていますか。","fu":"{誰|だれ}が{窓|まど}を{割|わ}ったか、{知|し}っていますか。","ru":"Вы знаете, кто разбил окно?"}]},{"id":"ga-suru","pattern":"〜がする","romaji":"ga suru","level":"N4","ru":"(запах, звук, вкус, ощущение) ощущается","en":"(a smell, sound, taste or feeling) is perceived","formation":"Noun + がする","formationRu":"существительное + がする","notes":"Употребляется с におい, 音, 声, 味 и 気 (〜気がする: «чувствовать, что»).","tags":["state","emotion"],"ex":[{"ja":"台所からいいにおいがする。","fu":"{台所|だいどころ}からいいにおいがする。","ru":"С кухни хорошо пахнет."},{"ja":"外で変な音がしました。","fu":"{外|そと}で{変|へん}な{音|おと}がしました。","ru":"Снаружи раздался странный звук."},{"ja":"このお茶は少し甘い味がする。","fu":"このお{茶|ちゃ}は{少|すこ}し{甘|あま}い{味|あじ}がする。","ru":"У этого чая слегка сладковатый вкус."}]},{"id":"garu","pattern":"〜がる","romaji":"garu","level":"N4","ru":"(кто-то другой) чувствует; проявляет чувство","en":"(someone else) feels; shows signs of feeling","formation":"i-Adj stem / na-Adj + がる","formationRu":"основа прилагательного на -い / прилагательное на -на + がる","notes":"Превращает прилагательные чувства (怖い, 寂しい, ほしい) в глаголы, описывающие, как, по-видимому, чувствует другой. Дополнение чувства берёт を.","tags":["emotion","appearance"],"ex":[{"ja":"妹は暗い所を怖がる。","fu":"{妹|いもうと}は{暗|くら}い{所|ところ}を{怖|こわ}がる。","ru":"Младшая сестра боится тёмных мест."},{"ja":"祖母は孫に会えなくて寂しがっている。","fu":"{祖母|そぼ}は{孫|まご}に{会|あ}えなくて{寂|さび}しがっている。","ru":"Бабушке грустно, что она не видит внуков."},{"ja":"息子は新しい自転車をほしがっている。","fu":"{息子|むすこ}は{新|あたら}しい{自転車|じてんしゃ}をほしがっている。","ru":"Сын очень хочет новый велосипед."}]},{"id":"ku-suru-ni-suru","pattern":"〜くする / 〜にする（make）","romaji":"ku suru / ni suru","level":"N4","ru":"сделать (что-то) каким-либо; привести что-то в состояние","en":"make (something) ...; change something to a state","formation":"i-Adj-ku + する / na-Adj + に + する / Noun + に + する","formationRu":"прилагательное на -い в форме -く + する / прилагательное на -на + に + する / существительное + に + する","notes":"Кто-то намеренно меняет что-то. Сравни 〜くなる / 〜になる, где изменение происходит само.","tags":["change"],"ex":[{"ja":"テレビの音を小さくしてください。","fu":"テレビの{音|おと}を{小|ちい}さくしてください。","ru":"Сделайте телевизор потише."},{"ja":"お客さんが来るから、部屋をきれいにしよう。","fu":"お{客|きゃく}さんが{来|く}るから、{部屋|へや}をきれいにしよう。","ru":"Придут гости, давайте приберём в комнате."},{"ja":"暑いので、髪を短くしました。","fu":"{暑|あつ}いので、{髪|かみ}を{短|みじか}くしました。","ru":"Из-за жары я коротко подстригся."}]},{"id":"kedo-keredomo","pattern":"〜けど / 〜けれども","romaji":"kedo / keredomo","level":"N4","ru":"но; хотя; (мягкое вступление)","en":"but; although; (soft lead-in)","formation":"Sentence + けど / けれども","formationRu":"предложение + けど / けれども","notes":"Разговорнее, чем が; けれども чуть формальнее けど. Часто служит мягким вступлением перед вопросом или просьбой.","tags":["contrast","casual"],"ex":[{"ja":"この店は高いけど、おいしい。","fu":"この{店|みせ}は{高|たか}いけど、おいしい。","ru":"В этом магазине дорого, зато вкусно."},{"ja":"すみません、駅に行きたいんですけど、どう行けばいいですか。","fu":"すみません、{駅|えき}に{行|い}きたいんですけど、どう{行|い}けばいいですか。","ru":"Простите, я хочу на станцию, как туда пройти?"},{"ja":"何度も電話したけれども、誰も出なかった。","fu":"{何|なん}{度|ど}も{電話|でんわ}したけれども、{誰|だれ}も{出|で}なかった。","ru":"Я звонил много раз, но никто не подошёл."}]},{"id":"koto-ga-aru","pattern":"〜ことがある","romaji":"koto ga aru","level":"N4","ru":"иногда; бывают случаи, когда","en":"sometimes; there are times when","formation":"Verb-dict / Verb-nai + ことがある","formationRu":"глагол в словарной форме / глагол в форме -ない + ことがある","notes":"Берёт словарную форму или форму на -ない. С прошедшей формой (〜たことがある) означает «делал когда-то».","tags":["tendency","time"],"ex":[{"ja":"忙しいときは、朝ご飯を食べないことがあります。","fu":"{忙|いそが}しいときは、{朝|あさ}ご{飯|はん}を{食|た}べないことがあります。","ru":"Когда я сильно занят, я иногда не завтракаю."},{"ja":"この道は冬になると、雪で通れなくなることがある。","fu":"この{道|みち}は{冬|ふゆ}になると、{雪|ゆき}で{通|とお}れなくなることがある。","ru":"Зимой эта дорога иногда бывает непроходима из-за снега."},{"ja":"週末は家族で料理をすることがある。","fu":"{週末|しゅうまつ}は{家族|かぞく}で{料理|りょうり}をすることがある。","ru":"По выходным мы иногда готовим всей семьёй."}]},{"id":"koto-ga-dekiru","pattern":"〜ことができる","romaji":"koto ga dekiru","level":"N4","ru":"мочь; иметь возможность","en":"can; be able to; be possible to","formation":"Verb-dict + ことができる","formationRu":"глагол в словарной форме + ことができる","notes":"Чуть формальнее потенциальной формы. Также о том, что возможно или разрешено (ここでたばこを吸うことはできません).","tags":["ability","possibility"],"ex":[{"ja":"この図書館では、本を二週間借りることができます。","fu":"この{図書館|としょかん}では、{本|ほん}を{二|に}{週間|しゅうかん}{借|か}りることができます。","ru":"В этой библиотеке книги можно брать на две недели."},{"ja":"妹はピアノを弾くことができる。","fu":"{妹|いもうと}はピアノを{弾|ひ}くことができる。","ru":"Младшая сестра умеет играть на фортепиано."},{"ja":"ここからは富士山を見ることができません。","fu":"ここからは{富士山|ふじさん}を{見|み}ることができません。","ru":"Отсюда нельзя увидеть гору Фудзи."}]},{"id":"koto-ni-suru","pattern":"〜ことにする","romaji":"koto ni suru","level":"N4","ru":"решить (что сделать)","en":"decide to","formation":"Verb-dict / Verb-nai + ことにする","formationRu":"глагол в словарной форме / глагол в форме -ない + ことにする","notes":"Решение, принятое самим говорящим; сравни 〜ことになる. 〜ことにしている (N3) — «сделать себе правилом».","tags":["decision"],"ex":[{"ja":"健康のために、毎朝歩くことにした。","fu":"{健康|けんこう}のために、{毎朝|まいあさ}{歩|ある}くことにした。","ru":"Ради здоровья я решил каждое утро гулять пешком."},{"ja":"高かったので、買わないことにしました。","fu":"{高|たか}かったので、{買|か}わないことにしました。","ru":"Было дорого, поэтому я решил не покупать."},{"ja":"もう遅いから、タクシーで帰ることにしよう。","fu":"もう{遅|おそ}いから、タクシーで{帰|かえ}ることにしよう。","ru":"Уже поздно — пожалуй, решу поехать домой на такси."}]},{"id":"koto-ni-naru","pattern":"〜ことになる","romaji":"koto ni naru","level":"N4","ru":"решили, что; вышло так, что","en":"it has been decided that; it turns out that","formation":"Verb-dict / Verb-nai + ことになる","formationRu":"глагол в словарной форме / глагол в форме -ない + ことになる","notes":"Подаёт решение как принятое другими людьми или обстоятельствами. Иногда так говорят и о своём решении, чтобы звучать менее категорично.","tags":["decision","result"],"ex":[{"ja":"来年の春から、名古屋の店で働くことになりました。","fu":"{来年|らいねん}の{春|はる}から、{名古屋|なごや}の{店|みせ}で{働|はたら}くことになりました。","ru":"С весны следующего года я буду работать в магазине в Нагое."},{"ja":"今度の日曜日、クラスのみんなでバーベキューをすることになった。","fu":"{今度|こんど}の{日曜日|にちようび}、クラスのみんなでバーベキューをすることになった。","ru":"В следующее воскресенье мы всем классом решили устроить барбекю."},{"ja":"友達の結婚式で、私がスピーチをすることになりました。","fu":"{友達|ともだち}の{結婚式|けっこんしき}で、{私|わたし}がスピーチをすることになりました。","ru":"На свадьбе друга мне предстоит произнести речь."}]},{"id":"sa","pattern":"〜さ","romaji":"sa","level":"N4","ru":"-ость (превращает прилагательное в существительное степени)","en":"-ness (turns an adjective into a noun of degree)","formation":"i-Adj stem + さ / na-Adj + さ","formationRu":"основа прилагательного на -い + さ / прилагательное на -на + さ","notes":"いい становится よさ. Часто для измерений (高さ, 重さ, 大きさ, 長さ).","tags":["nominalization","degree"],"ex":[{"ja":"この橋の長さはどのくらいですか。","fu":"この{橋|はし}の{長|なが}さはどのくらいですか。","ru":"Какая длина у этого моста?"},{"ja":"山の上の寒さにびっくりした。","fu":"{山|やま}の{上|うえ}の{寒|さむ}さにびっくりした。","ru":"Я поразился тому, как холодно на вершине горы."},{"ja":"この仕事の大変さは、やってみないと分からない。","fu":"この{仕事|しごと}の{大変|たいへん}さは、やってみないと{分|わ}からない。","ru":"Насколько трудна эта работа, непонятно, пока сам не попробуешь."}]},{"id":"sasete-kudasai","pattern":"〜させてください","romaji":"sasete kudasai","level":"N4","ru":"позвольте мне, пожалуйста","en":"please let me (do)","formation":"Verb-nai stem + せてください (Group 1) / Verb-nai stem + させてください (Group 2)","formationRu":"основа формы -ない + せてください (1-я группа) / основа формы -ない + させてください (2-я группа)","notes":"Построено на форме на -て каузатива (する → させて). 〜させていただけませんか вежливее.","tags":["request","permission"],"ex":[{"ja":"少し考えさせてください。","fu":"{少|すこ}し{考|かんが}えさせてください。","ru":"Позвольте мне немного подумать."},{"ja":"今日は私に払わせてください。","fu":"{今日|きょう}は{私|わたし}に{払|はら}わせてください。","ru":"Сегодня позвольте мне заплатить."},{"ja":"体の調子が悪いので、今日は早く帰らせてください。","fu":"{体|からだ}の{調子|ちょうし}が{悪|わる}いので、{今日|きょう}は{早|はや}く{帰|かえ}らせてください。","ru":"Я плохо себя чувствую, позвольте мне сегодня уйти пораньше."}]},{"id":"shi","pattern":"〜し","romaji":"shi","level":"N4","ru":"а кроме того; и к тому же (перечисление причин)","en":"and what's more; and besides (listing reasons)","formation":"Verb-plain / i-Adj + し / na-Adj + だ + し / Noun + だ + し","formationRu":"простая форма / прилагательное на -い + し / прилагательное на -на + だ + し / существительное + だ + し","notes":"Перечисляет несколько причин или доводов. Одно-единственное し намекает, что причины есть и другие.","tags":["reason","addition"],"ex":[{"ja":"この部屋は広いし、駅から近いし、とても気に入っています。","fu":"この{部屋|へや}は{広|ひろ}いし、{駅|えき}から{近|ちか}いし、とても{気|き}に{入|い}っています。","ru":"Эта комната и просторная, и рядом со станцией — мне она очень нравится."},{"ja":"今日は雨だし、疲れているし、どこにも行きたくない。","fu":"{今日|きょう}は{雨|あめ}だし、{疲|つか}れているし、どこにも{行|い}きたくない。","ru":"Сегодня и дождь, и устал — никуда не хочется идти."},{"ja":"もう遅いし、そろそろ帰ろうか。","fu":"もう{遅|おそ}いし、そろそろ{帰|かえ}ろうか。","ru":"Уже поздно, пора и домой."}]},{"id":"shika-nai","pattern":"〜しか〜ない","romaji":"shika ... nai","level":"N4","ru":"только; ничего, кроме","en":"only; nothing but","formation":"Noun + しか + Verb-nai","formationRu":"существительное + しか + глагол в форме -ない","notes":"Всегда в паре с отрицательным глаголом. По сравнению с だけ подчёркивает, что количество мало или его недостаточно.","tags":["limitation","negation"],"ex":[{"ja":"財布に五百円しかない。","fu":"{財布|さいふ}に{五|ご}{百|ひゃく}{円|えん}しかない。","ru":"В кошельке всего пятьсот иен."},{"ja":"このことは、あなたにしか話していません。","fu":"このことは、あなたにしか{話|はな}していません。","ru":"Об этом я рассказывал только тебе."},{"ja":"朝はコーヒーしか飲みません。","fu":"{朝|あさ}はコーヒーしか{飲|の}みません。","ru":"Утром я пью только кофе."}]},{"id":"sugiru","pattern":"〜すぎる","romaji":"sugiru","level":"N4","ru":"слишком; чрезмерно; чересчур","en":"too; too much; excessively","formation":"Verb-stem / i-Adj stem / na-Adj + すぎる","formationRu":"основа масу-формы / основа прилагательного на -い / прилагательное на -на + すぎる","notes":"Изменяется как глагол 2-й группы (すぎた, すぎて). いい → よすぎる, а прилагательное ない → なさすぎる.","tags":["degree"],"ex":[{"ja":"ゆうべ飲みすぎて、頭が痛い。","fu":"ゆうべ{飲|の}みすぎて、{頭|あたま}が{痛|いた}い。","ru":"Вчера вечером я слишком много выпил, и теперь у меня болит голова."},{"ja":"この靴は私には大きすぎます。","fu":"この{靴|くつ}は{私|わたし}には{大|おお}きすぎます。","ru":"Эти туфли мне слишком велики."},{"ja":"この問題は簡単すぎて、つまらない。","fu":"この{問題|もんだい}は{簡単|かんたん}すぎて、つまらない。","ru":"Эта задача слишком лёгкая, поэтому неинтересная."}]},{"id":"zutsu","pattern":"〜ずつ","romaji":"zutsu","level":"N4","ru":"по (столько-то, каждому); каждый раз по; понемногу","en":"each; at a time; little by little","formation":"Noun (quantity) + ずつ","formationRu":"существительное (количество) + ずつ","notes":null,"tags":["quantity"],"ex":[{"ja":"りんごを一人に二つずつ配った。","fu":"りんごを{一人|ひとり}に{二|ふた}つずつ{配|くば}った。","ru":"Я раздал каждому по два яблока."},{"ja":"毎日少しずつ漢字を覚えています。","fu":"{毎日|まいにち}{少|すこ}しずつ{漢字|かんじ}を{覚|おぼ}えています。","ru":"Каждый день я понемногу запоминаю кандзи."},{"ja":"一人ずつ部屋に入ってください。","fu":"{一人|ひとり}ずつ{部屋|へや}に{入|はい}ってください。","ru":"Пожалуйста, входите в комнату по одному."}]},{"id":"serareru-saserareru","pattern":"〜せられる / 〜させられる","romaji":"serareru / saserareru","level":"N4","ru":"быть вынужденным сделать (против воли)","en":"be made to do (against one's will)","formation":"Verb-nai stem + せられる (Group 1; short form される) / Verb-nai stem + させられる (Group 2)","formationRu":"основа формы -ない + せられる (1-я группа; краткая форма される) / основа формы -ない + させられる (2-я группа)","notes":"Неправильные: する → させられる, 来る → 来させられる. Краткая форма 1-й группы (待たされる) обычна в речи, но не у глаголов на す (話させられる).","tags":["voice","conjugation"],"ex":[{"ja":"子どものころ、母に毎日ピアノを練習させられた。","fu":"{子|こ}どものころ、{母|はは}に{毎日|まいにち}ピアノを{練習|れんしゅう}させられた。","ru":"В детстве мама заставляла меня каждый день заниматься на фортепиано."},{"ja":"駅で三十分も待たされました。","fu":"{駅|えき}で{三十分|さんじゅっぷん}も{待|ま}たされました。","ru":"На станции меня заставили ждать целых тридцать минут."},{"ja":"会社の飲み会で歌を歌わされた。","fu":"{会社|かいしゃ}の{飲|の}み{会|かい}で{歌|うた}を{歌|うた}わされた。","ru":"На корпоративе меня заставили петь."}]},{"id":"seru-saseru","pattern":"〜せる / 〜させる","romaji":"seru / saseru","level":"N4","ru":"заставить кого-то сделать; позволить кому-то сделать (каузатив)","en":"make someone do; let someone do (causative)","formation":"Verb-nai stem + せる (Group 1) / Verb-nai stem + させる (Group 2)","formationRu":"основа формы -ない + せる (1-я группа) / основа формы -ない + させる (2-я группа)","notes":"Неправильные: する → させる, 来る → 来させる. С непереходными глаголами лицо берёт を; с переходными — に. «Заставить» или «позволить» решает контекст.","tags":["voice","conjugation"],"ex":[{"ja":"母は毎日弟に野菜を食べさせる。","fu":"{母|はは}は{毎日|まいにち}{弟|おとうと}に{野菜|やさい}を{食|た}べさせる。","ru":"Мама каждый день заставляет младшего брата есть овощи."},{"ja":"コーチは毎日、選手たちを走らせた。","fu":"コーチは{毎日|まいにち}、{選手|せんしゅ}たちを{走|はし}らせた。","ru":"Тренер каждый день заставлял спортсменов бегать."},{"ja":"息子が行きたいと言ったので、一人で旅行に行かせました。","fu":"{息子|むすこ}が{行|い}きたいと{言|い}ったので、{一人|ひとり}で{旅行|りょこう}に{行|い}かせました。","ru":"Сын сказал, что хочет поехать, поэтому я отпустил его в поездку одного."}]},{"id":"sou-da-appearance","pattern":"〜そうだ（appearance）","romaji":"sou da (appearance)","level":"N4","ru":"похоже на; кажется; вот-вот (что-то произойдёт)","en":"looks like; seems; looks about to","formation":"Verb-stem / i-Adj stem / na-Adj + そうだ","formationRu":"основа масу-формы / основа прилагательного на -い / прилагательное на -на + そうだ","notes":"Оценка на основе того, что видно. いい → よさそう, ない → なさそう. Не употребляется с прилагательными, называющими явно видимые признаки (赤い, かわいい); かわいそう означает «вызывает жалость».","tags":["appearance","conjecture"],"ex":[{"ja":"そのカレー、辛そうだね。","fu":"そのカレー、{辛|から}そうだね。","ru":"Эта карри, похоже, очень острая."},{"ja":"空が暗いですね。雨が降りそうです。","fu":"{空|そら}が{暗|くら}いですね。{雨|あめ}が{降|ふ}りそうです。","ru":"Небо тёмное. Похоже, будет дождь."},{"ja":"久しぶりに会った祖父は元気そうだった。","fu":"{久|ひさ}しぶりに{会|あ}った{祖父|そふ}は{元気|げんき}そうだった。","ru":"Дед, которого я давно не видел, выглядел бодрым."}]},{"id":"sou-da-hearsay","pattern":"〜そうだ（hearsay）","romaji":"sou da (hearsay)","level":"N4","ru":"слышал, что; говорят, что","en":"I heard that; they say that","formation":"Verb-plain / i-Adj + そうだ / na-Adj + だ + そうだ / Noun + だ + そうだ","formationRu":"простая форма / прилагательное на -い + そうだ / прилагательное на -на + だ + そうだ / существительное + だ + そうだ","notes":"Присоединяется к полной простой форме, в отличие от そうда «похоже», которое присоединяется к основе. Не имеет ни прошедшего времени, ни отрицания.","tags":["hearsay"],"ex":[{"ja":"天気予報では、明日は雪が降るそうです。","fu":"{天気|てんき}{予報|よほう}では、{明日|あした}は{雪|ゆき}が{降|ふ}るそうです。","ru":"По прогнозу погоды, завтра обещают снег."},{"ja":"駅前の本屋は来月なくなるそうだ。","fu":"{駅前|えきまえ}の{本屋|ほんや}は{来月|らいげつ}なくなるそうだ。","ru":"Говорят, книжный магазин перед станцией закроется в следующем месяце."},{"ja":"リンさんのお兄さんは医者だそうです。","fu":"リンさんのお{兄|にい}さんは{医者|いしゃ}だそうです。","ru":"Говорят, старший брат Лин — врач."}]},{"id":"tagaru","pattern":"〜たがる","romaji":"tagaru","level":"N4","ru":"(кто-то другой) хочет","en":"(someone else) wants to","formation":"Verb-stem + たがる","formationRu":"основа масу-формы + たがる","notes":"Употребляется о других людях, поскольку их желания нельзя знать напрямую. Актуальное желание обычно передают через 〜たがっている.","tags":["desire"],"ex":[{"ja":"子どもたちは外で遊びたがっている。","fu":"{子|こ}どもたちは{外|そと}で{遊|あそ}びたがっている。","ru":"Детям хочется играть на улице."},{"ja":"弟はいつも私のゲームをやりたがる。","fu":"{弟|おとうと}はいつも{私|わたし}のゲームをやりたがる。","ru":"Младший брат всё время хочет играть в мои игры."},{"ja":"犬が散歩に行きたがっています。","fu":"{犬|いぬ}が{散歩|さんぽ}に{行|い}きたがっています。","ru":"Собака просится на прогулку."}]},{"id":"ta-bakari","pattern":"〜たばかり","romaji":"ta bakari","level":"N4","ru":"только что сделать","en":"have just done","formation":"Verb-ta + ばかり","formationRu":"глагол в форме -た + ばかり","notes":"Показывает, что говорящему кажется, будто прошло мало времени, даже если это было несколько недель назад. 〜たところ — лишь о нескольких мгновениях назад.","tags":["time","completion"],"ex":[{"ja":"日本に来たばかりなので、まだ日本語がよく分かりません。","fu":"{日本|にほん}に{来|き}たばかりなので、まだ{日本語|にほんご}がよく{分|わ}かりません。","ru":"Я только что приехал в Японию и ещё плохо понимаю японский."},{"ja":"さっき昼ご飯を食べたばかりだから、おなかがいっぱいだ。","fu":"さっき{昼|ひる}ご{飯|はん}を{食|た}べたばかりだから、おなかがいっぱいだ。","ru":"Я совсем недавно пообедал, поэтому сыт."},{"ja":"買ったばかりの傘をなくしてしまった。","fu":"{買|か}ったばかりの{傘|かさ}をなくしてしまった。","ru":"Я потерял только что купленный зонт."}]},{"id":"tame-ni","pattern":"〜ために","romaji":"tame ni","level":"N4","ru":"чтобы; ради; из-за","en":"in order to; for (the sake of); because of","formation":"Verb-dict / Verb-ta / Noun + の + ために","formationRu":"глагол в словарной форме / глагол в форме -た / существительное + の + ために","notes":"Для выражения цели глагол должен обозначать то, чем субъект может управлять (сравни 〜ように). Значение «из-за» звучит довольно формально.","tags":["purpose","reason"],"ex":[{"ja":"日本の大学に入るために、毎日勉強しています。","fu":"{日本|にほん}の{大学|だいがく}に{入|はい}るために、{毎日|まいにち}{勉強|べんきょう}しています。","ru":"Я занимаюсь каждый день, чтобы поступить в японский университет."},{"ja":"家族のために、一生懸命働いている。","fu":"{家族|かぞく}のために、{一生懸命|いっしょうけんめい}{働|はたら}いている。","ru":"Я усердно работаю ради семьи."},{"ja":"大雪のために、電車が止まりました。","fu":"{大雪|おおゆき}のために、{電車|でんしゃ}が{止|と}まりました。","ru":"Из-за сильного снегопада поезда остановились."}]},{"id":"tara","pattern":"〜たら","romaji":"tara","level":"N4","ru":"если; когда; после того как","en":"if; when; after","formation":"Verb-ta + ら / i-Adj stem + かったら / na-Adj + だったら / Noun + だったら","formationRu":"глагол в форме -た + ら / основа прилагательного на -い + かったら / прилагательное на -на + だったら / существительное + だったら","notes":"Самое универсальное условное и очень частое в разговорной речи. О событиях, которые наверняка произойдут, означает «когда/после».","tags":["condition","time"],"ex":[{"ja":"駅に着いたら、電話してください。","fu":"{駅|えき}に{着|つ}いたら、{電話|でんわ}してください。","ru":"Когда придёте на станцию, позвоните."},{"ja":"もし明日雨だったら、家で映画を見よう。","fu":"もし{明日|あした}{雨|あめ}だったら、{家|いえ}で{映画|えいが}を{見|み}よう。","ru":"Если завтра будет дождь, давай посмотрим фильм дома."},{"ja":"暑かったら、窓を開けてもいいですよ。","fu":"{暑|あつ}かったら、{窓|まど}を{開|あ}けてもいいですよ。","ru":"Если жарко, можно и открыть окно."}]},{"id":"tara-dou","pattern":"〜たらどう","romaji":"tara dou","level":"N4","ru":"почему бы не ...?; как насчёт ...?","en":"why don't you ...?; how about ...?","formation":"Verb-ta + らどう","formationRu":"глагол в форме -た + らどう","notes":"Часто сокращается до 〜たら？. Начальству может прозвучать навязчиво; вежливая версия — 〜たらいかがですか.","tags":["suggestion","advice"],"ex":[{"ja":"疲れているなら、少し休んだらどう？","fu":"{疲|つか}れているなら、{少|すこ}し{休|やす}んだらどう？","ru":"Если устал, почему бы не отдохнуть немного?"},{"ja":"分からなければ、先生に聞いてみたらどうですか。","fu":"{分|わ}からなければ、{先生|せんせい}に{聞|き}いてみたらどうですか。","ru":"Если не понятно, попробуйте спросить у учителя."}]},{"id":"darou","pattern":"〜だろう","romaji":"darou","level":"N4","ru":"наверное; полагаю (простая форма от でしょう)","en":"probably; I suppose (plain form of でしょう)","formation":"Verb-plain / i-Adj / na-Adj / Noun + だろう","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + だろう","notes":"Часто в письменной речи и в непринуждённой речи мужчин; でしょう — вежливая форма. Часто с たぶん или きっと, либо как 〜だろうと思う.","tags":["conjecture"],"ex":[{"ja":"明日はたぶん晴れるだろう。","fu":"{明日|あした}はたぶん{晴|は}れるだろう。","ru":"Завтра, наверное, будет ясно."},{"ja":"彼女はもう家に着いただろう。","fu":"{彼女|かのじょ}はもう{家|いえ}に{着|つ}いただろう。","ru":"Она, должно быть, уже добралась до дома."},{"ja":"この問題は子どもには難しいだろうと思います。","fu":"この{問題|もんだい}は{子|こ}どもには{難|むずか}しいだろうと{思|おも}います。","ru":"Думаю, детям эта задача будет трудна."}]},{"id":"tsumori","pattern":"〜つもり","romaji":"tsumori","level":"N4","ru":"намерен; собираюсь; иметь планы","en":"intend to; plan to","formation":"Verb-dict / Verb-nai + つもり","formationRu":"глагол в словарной форме / глагол в форме -ない + つもり","notes":"Выражает твёрдое личное намерение. 〜つもりはない — «не намерен». Вопрос, заданный начальству (〜つもりですか), может прозвучать резковато.","tags":["intention"],"ex":[{"ja":"夏休みは北海道を旅行するつもりです。","fu":"{夏休|なつやす}みは{北海道|ほっかいどう}を{旅行|りょこう}するつもりです。","ru":"На летних каникулах я собираюсь путешествовать по Хоккайдо."},{"ja":"今日はお酒を飲まないつもりです。","fu":"{今日|きょう}はお{酒|さけ}を{飲|の}まないつもりです。","ru":"Сегодня я решил не пить алкоголь."},{"ja":"大学を出たら、どうするつもりですか。","fu":"{大学|だいがく}を{出|で}たら、どうするつもりですか。","ru":"Что вы собираетесь делать после окончания университета?"}]},{"id":"te-ageru","pattern":"〜てあげる","romaji":"te ageru","level":"N4","ru":"сделать что-то для кого-то (как услугу)","en":"do something for someone (as a favor)","formation":"Verb-te + あげる","formationRu":"глагол в форме -て + あげる","notes":"Сказанное напрямую старшему по положению может прозвучать снисходительно; лучше употребить скромное お〜しましょうか (お持ちしましょうか).","tags":["giving-receiving"],"ex":[{"ja":"妹の宿題を手伝ってあげました。","fu":"{妹|いもうと}の{宿題|しゅくだい}を{手伝|てつだ}ってあげました。","ru":"Я помог младшей сестре с домашним заданием."},{"ja":"道に迷っている人に、駅までの行き方を教えてあげた。","fu":"{道|みち}に{迷|まよ}っている{人|ひと}に、{駅|えき}までの{行|い}き{方|かた}を{教|おし}えてあげた。","ru":"Я подсказал заблудившемуся человеку, как добраться до станции."},{"ja":"重そうだね。持ってあげようか。","fu":"{重|おも}そうだね。{持|も}ってあげようか。","ru":"Похоже, тяжело. Давай я понесу это за тебя?"}]},{"id":"te-aru","pattern":"〜てある","romaji":"te aru","level":"N4","ru":"сделано (и остаётся в таком состоянии); результат намеренного действия","en":"has been done (and stays that way); resulting state of a deliberate action","formation":"Verb-te + ある","formationRu":"глагол в форме -て + ある","notes":"Употребляется с переходными глаголами, дополнение обычно с частицей が. Подразумевается, что кто-то сделал это намеренно, в отличие от 〜ている с непереходными глаголами (窓が開いている).","tags":["state","result"],"ex":[{"ja":"入り口に地図がはってあります。","fu":"{入|い}り{口|ぐち}に{地図|ちず}がはってあります。","ru":"У входа приклеена карта."},{"ja":"テーブルの上にお皿が並べてあった。","fu":"テーブルの{上|うえ}にお{皿|さら}が{並|なら}べてあった。","ru":"На столе были расставлены тарелки."},{"ja":"ビールなら冷蔵庫に入れてあるよ。","fu":"ビールなら{冷蔵庫|れいぞうこ}に{入|い}れてあるよ。","ru":"Пиво я поставил в холодильник."}]},{"id":"te-iku","pattern":"〜ていく","romaji":"te iku","level":"N4","ru":"сделать и уйти; продолжать делать (отныне и в дальнейшем)","en":"do something and go; go on doing (from now into the future)","formation":"Verb-te + いく","formationRu":"глагол в форме -て + いく","notes":"Движение или изменение от говорящего, либо от настоящего момента в будущее. Сравните 〜てくる.","tags":["change","sequence"],"ex":[{"ja":"雨が降りそうだから、傘を持っていきます。","fu":"{雨|あめ}が{降|ふ}りそうだから、{傘|かさ}を{持|も}っていきます。","ru":"Обещается дождь, поэтому я возьму с собой зонт."},{"ja":"これからもっと寒くなっていくでしょう。","fu":"これからもっと{寒|さむ}くなっていくでしょう。","ru":"И дальше будет становиться всё холоднее."},{"ja":"時間があるなら、お茶を飲んでいきませんか。","fu":"{時間|じかん}があるなら、お{茶|ちゃ}を{飲|の}んでいきませんか。","ru":"Если у тебя есть время, давай сначала выпьем чаю."}]},{"id":"te-oku","pattern":"〜ておく","romaji":"te oku","level":"N4","ru":"сделать заранее (в качестве подготовки); сделать и оставить как есть","en":"do in advance (to prepare); do and leave as is","formation":"Verb-te + おく","formationRu":"глагол в форме -て + おく","notes":"В разговорной речи 〜ておく часто превращается в 〜とく (買っとく), а 〜でおく — в 〜どく (読んどく).","tags":["purpose","state"],"ex":[{"ja":"旅行の前に、ホテルを予約しておきます。","fu":"{旅行|りょこう}の{前|まえ}に、ホテルを{予約|よやく}しておきます。","ru":"Перед поездкой я заранее бронирую гостиницу."},{"ja":"パーティーのために、飲み物を冷やしておいた。","fu":"パーティーのために、{飲|の}み{物|もの}を{冷|ひ}やしておいた。","ru":"К вечеринке я заранее охладил напитки."},{"ja":"エアコンはつけておいてください。","fu":"エアコンはつけておいてください。","ru":"Пожалуйста, оставьте кондиционер включённым."}]},{"id":"te-kudasaru-te-itadaku","pattern":"〜てくださる / 〜ていただく","romaji":"te kudasaru / te itadaku","level":"N4","ru":"(почтительно) кто-то любезно делает для меня; (скромно) удостоиться того, что кто-то сделал для меня","en":"(honorific) someone kindly does for me; (humble) I receive the favor of someone doing","formation":"Verb-te + くださる / Verb-te + いただく","formationRu":"глагол в форме -て + くださる / глагол в форме -て + いただく","notes":"くださる — почтительный вариант くれる (в форме ます: くださいます); いただく — скромный вариант もらう.","tags":["giving-receiving","honorific","humble"],"ex":[{"ja":"先生が私の作文を直してくださいました。","fu":"{先生|せんせい}が{私|わたし}の{作文|さくぶん}を{直|なお}してくださいました。","ru":"Учитель исправил моё сочинение."},{"ja":"ホテルの方に、おいしい店を教えていただきました。","fu":"ホテルの{方|かた}に、おいしい{店|みせ}を{教|おし}えていただきました。","ru":"В гостинице мне подсказали, где можно вкусно поесть."},{"ja":"今日は来ていただいて、ありがとうございました。","fu":"{今日|きょう}は{来|き}ていただいて、ありがとうございました。","ru":"Большое спасибо за то, что вы сегодня пришли."}]},{"id":"te-kuru","pattern":"〜てくる","romaji":"te kuru","level":"N4","ru":"сделать и вернуться; прийти делая; (об изменении) вплоть до сейчас; начать","en":"do something and come back; come doing; (change) up to now; start to","formation":"Verb-te + くる","formationRu":"глагол в форме -て + くる","notes":"Движение или изменение по направлению к говорящему, либо от прошлого до настоящего. 行ってきます буквально значит «я пойду и вернусь».","tags":["change","sequence"],"ex":[{"ja":"ちょっとコンビニに行ってきます。","fu":"ちょっとコンビニに{行|い}ってきます。","ru":"Я сейчас сбегаю в ближайший магазин."},{"ja":"日本語が少しずつ分かってきた。","fu":"{日本語|にほんご}が{少|すこ}しずつ{分|わ}かってきた。","ru":"Я стал понемногу понимать японский язык."},{"ja":"おなかがすいてきた。","fu":"おなかがすいてきた。","ru":"Я начал чувствовать голод."}]},{"id":"te-kuremasen-ka-te-itadakemasen-ka","pattern":"〜てくれませんか / 〜ていただけませんか","romaji":"te kuremasen ka / te itadakemasen ka","level":"N4","ru":"не могли бы вы ...? (вежливая просьба)","en":"could you please ...? (polite request)","formation":"Verb-te + くれませんか / Verb-te + いただけませんか","formationRu":"глагол в форме -て + くれませんか / глагол в форме -て + いただけませんか","notes":"Мягче, чем 〜てください. Вежливость растёт по цепочке: 〜てくれませんか → 〜てもらえませんか → 〜ていただけませんか.","tags":["request","politeness"],"ex":[{"ja":"すみません、写真を撮ってくれませんか。","fu":"すみません、{写真|しゃしん}を{撮|と}ってくれませんか。","ru":"Извините, не могли бы вы меня сфотографировать?"},{"ja":"この書類の書き方を教えていただけませんか。","fu":"この{書類|しょるい}の{書|か}き{方|かた}を{教|おし}えていただけませんか。","ru":"Не могли бы вы объяснить, как заполнять этот документ?"},{"ja":"もう少し大きい声で話していただけませんか。","fu":"もう{少|すこ}し{大|おお}きい{声|こえ}で{話|はな}していただけませんか。","ru":"Не могли бы вы говорить чуть громче?"}]},{"id":"te-kureru","pattern":"〜てくれる","romaji":"te kureru","level":"N4","ru":"кто-то сделал что-то для меня (или для моих близких)","en":"someone does something for me (or my group)","formation":"Verb-te + くれる","formationRu":"глагол в форме -て + くれる","notes":"Подлежащим является тот, кто сделал услугу, а выгоду получает говорящий или близкий ему человек.","tags":["giving-receiving"],"ex":[{"ja":"友達が引っ越しを手伝ってくれた。","fu":"{友達|ともだち}が{引|ひ}っ{越|こ}しを{手伝|てつだ}ってくれた。","ru":"Друг помог мне с переездом."},{"ja":"父が駅まで車で送ってくれました。","fu":"{父|ちち}が{駅|えき}まで{車|くるま}で{送|おく}ってくれました。","ru":"Отец на машине подвёз меня до станции."},{"ja":"母が毎朝お弁当を作ってくれます。","fu":"{母|はは}が{毎朝|まいあさ}お{弁当|べんとう}を{作|つく}ってくれます。","ru":"Мама каждое утро собирает мне обед с собой."}]},{"id":"te-shimau-chau","pattern":"〜てしまう / 〜ちゃう","romaji":"te shimau / chau","level":"N4","ru":"сделать до конца; сделать случайно; в итоге сделать (с сожалением)","en":"finish completely; do by accident; end up doing (with regret)","formation":"Verb-te + しまう","formationRu":"глагол в форме -て + しまう","notes":"В речи 〜てしまう сокращается до 〜ちゃう, а 〜でしまう — до 〜じゃう (飲んじゃう).","tags":["completion","regret","casual"],"ex":[{"ja":"電車に傘を忘れてしまいました。","fu":"{電車|でんしゃ}に{傘|かさ}を{忘|わす}れてしまいました。","ru":"Я, к сожалению, забыл зонт в поезде."},{"ja":"この本はおもしろくて、一晩で読んでしまった。","fu":"この{本|ほん}はおもしろくて、{一晩|ひとばん}で{読|よ}んでしまった。","ru":"Эта книга такая интересная, что я прочитал её за одну ночь."},{"ja":"あ、ケーキを全部食べちゃった。","fu":"あ、ケーキを{全部|ぜんぶ}{食|た}べちゃった。","ru":"Ой, я съел весь торт."}]},{"id":"te-hoshii","pattern":"〜てほしい","romaji":"te hoshii","level":"N4","ru":"хотеть, чтобы кто-то сделал","en":"want someone to do","formation":"Verb-te + ほしい / Verb-nai + で + ほしい","formationRu":"глагол в форме -て + ほしい / глагол в форме -ない + で + ほしい","notes":"Тот, кто должен действовать, отмечается частицей に. Сказанное начальству может прозвучать требовательно; 〜ていただきたいです вежливее.","tags":["desire","request"],"ex":[{"ja":"もう少しゆっくり話してほしいです。","fu":"もう{少|すこ}しゆっくり{話|はな}してほしいです。","ru":"Я хотел бы, чтобы вы говорили помедленнее."},{"ja":"この話は誰にも言わないでほしい。","fu":"この{話|はなし}は{誰|だれ}にも{言|い}わないでほしい。","ru":"Прошу никому об этом не говорить."},{"ja":"早く春が来てほしいなあ。","fu":"{早|はや}く{春|はる}が{来|き}てほしいなあ。","ru":"Хочется, чтобы весна пришла поскорее."}]},{"id":"te-miru","pattern":"〜てみる","romaji":"te miru","level":"N4","ru":"попробовать сделать (чтобы посмотреть, как это); сделать на пробу","en":"try doing (to see what it is like)","formation":"Verb-te + みる","formationRu":"глагол в форме -て + みる","notes":"Означает попробовать что-то, чтобы увидеть результат, а не прилагать усилие ради чего-то трудного.","tags":["attempt"],"ex":[{"ja":"このシャツ、着てみてもいいですか。","fu":"このシャツ、{着|き}てみてもいいですか。","ru":"Можно я примерю эту рубашку?"},{"ja":"新しくできたラーメン屋に行ってみた。","fu":"{新|あたら}しくできたラーメン{屋|や}に{行|い}ってみた。","ru":"Я сходил в недавно открывшийся ресторан, чтобы попробовать рамен."},{"ja":"日本の料理を自分で作ってみたいです。","fu":"{日本|にほん}の{料理|りょうり}を{自分|じぶん}で{作|つく}ってみたいです。","ru":"Я хотел бы сам попробовать приготовить японское блюдо."}]},{"id":"te-mo-de-mo","pattern":"〜ても / 〜でも","romaji":"te mo / de mo","level":"N4","ru":"даже если; хотя","en":"even if; even though","formation":"Verb-te + も / i-Adj-ku + ても / na-Adj + でも / Noun + でも","formationRu":"глагол в форме -て + も / прилагательное на -い в форме -く + ても / прилагательное на -на + でも / существительное + でも","notes":"С вопросительными словами или いくら означает «сколько бы ни...» (何を食べても, いくら待っても).","tags":["concession","condition"],"ex":[{"ja":"雨が降っても、試合はあります。","fu":"{雨|あめ}が{降|ふ}っても、{試合|しあい}はあります。","ru":"Даже если пойдёт дождь, игра состоится."},{"ja":"いくら練習しても、なかなか上手になりません。","fu":"いくら{練習|れんしゅう}しても、なかなか{上手|じょうず}になりません。","ru":"Сколько ни тренируйся, а получается плохо."},{"ja":"日曜日でも、この店は開いています。","fu":"{日曜日|にちようび}でも、この{店|みせ}は{開|あ}いています。","ru":"Этот магазин открыт даже по воскресеньям."}]},{"id":"te-morau","pattern":"〜てもらう","romaji":"te morau","level":"N4","ru":"попросить кого-то сделать (для меня); добиться, чтобы кто-то сделал","en":"have someone do something (for me); get someone to do","formation":"Verb-te + もらう","formationRu":"глагол в форме -て + もらう","notes":"Подлежащим становится тот, кто получил услугу, а человек, выполнивший действие, помечается частицей に.","tags":["giving-receiving"],"ex":[{"ja":"先輩にレポートを見てもらった。","fu":"{先輩|せんぱい}にレポートを{見|み}てもらった。","ru":"Я попросил старшего товарища проверить мой реферат."},{"ja":"友達に写真を撮ってもらった。","fu":"{友達|ともだち}に{写真|しゃしん}を{撮|と}ってもらった。","ru":"Я попросил друга сфотографировать меня."},{"ja":"分からないところを先生に説明してもらいました。","fu":"{分|わ}からないところを{先生|せんせい}に{説明|せつめい}してもらいました。","ru":"Учитель объяснил мне непонятные места."}]},{"id":"te-mo-kamawanai","pattern":"〜ても構わない","romaji":"te mo kamawanai","level":"N4","ru":"не возражаю против; ничего страшного, если","en":"don't mind if; it's fine if","formation":"Verb-te + も構わない / i-Adj-ku + ても構わない / na-Adj + でも構わない / Noun + でも構わない","formationRu":"глагол в форме -て + も構わない / прилагательное на -い в форме -く + ても構わない / прилагательное на -на + でも構わない / существительное + でも構わない","notes":"Чуть формальнее, чем 〜てもいい. 〜なくても構わない — «ничего страшного, если не».","tags":["permission"],"ex":[{"ja":"ここに荷物を置いても構いませんか。","fu":"ここに{荷物|にもつ}を{置|お}いても{構|かま}いませんか。","ru":"Ничего, если я оставлю здесь багаж?"},{"ja":"少しぐらい高くても構わないから、いい辞書を買いたい。","fu":"{少|すこ}しぐらい{高|たか}くても{構|かま}わないから、いい{辞書|じしょ}を{買|か}いたい。","ru":"Пусть словарь будет немного дороже — это не важно, я хочу купить хороший."},{"ja":"返事は明日でも構いませんよ。","fu":"{返事|へんじ}は{明日|あした}でも{構|かま}いませんよ。","ru":"Ответить можно и завтра — ничего страшного."}]},{"id":"te-reason","pattern":"〜て（reason）","romaji":"te (reason)","level":"N4","ru":"потому что; поэтому (причина чувства или состояния)","en":"because; so (cause of a feeling or state)","formation":"Verb-te / i-Adj stem + くて / na-Adj + で / Noun + で","formationRu":"глагол в форме -て / основа прилагательного на -い + くて / прилагательное на -на + で / существительное + で","notes":"Вторая часть обычно чувство, потенциальная форма или результат, а не просьба или намерение (для них берут から или ので). Отрицание: 〜なくて (会えなくて寂しい).","tags":["reason"],"ex":[{"ja":"ニュースを聞いて、びっくりしました。","fu":"ニュースを{聞|き}いて、びっくりしました。","ru":"Я услышал новости и очень удивился."},{"ja":"このスープは熱くて、飲めません。","fu":"このスープは{熱|あつ}くて、{飲|の}めません。","ru":"Этот суп такой горячий, что его не выпьешь."},{"ja":"かぜで学校を休みました。","fu":"かぜで{学校|がっこう}を{休|やす}みました。","ru":"Из-за простуды я не пошёл в школу."}]},{"id":"de-gozaimasu","pattern":"〜でございます","romaji":"de gozaimasu","level":"N4","ru":"есть; являюсь (очень вежливая связка)","en":"is; am; are (very polite copula)","formation":"Noun / na-Adj + でございます","formationRu":"существительное / прилагательное на -на + でございます","notes":"Очень вежливый вариант です, типичный для персонала магазинов и гостиниц в разговоре с клиентами. ございます само по себе — вежливая форма あります.","tags":["politeness","formal"],"ex":[{"ja":"お手洗いはあちらでございます。","fu":"お{手洗|てあら}いはあちらでございます。","ru":"Туалет находится вон там."},{"ja":"こちらが、お部屋のかぎでございます。","fu":"こちらが、お{部屋|へや}のかぎでございます。","ru":"Вот ключ от вашей комнаты."},{"ja":"はい、山田商店でございます。","fu":"はい、{山田|やまだ}{商店|しょうてん}でございます。","ru":"Да, вас слушает магазин «Ямада»."}]},{"id":"de-mo-suggestion","pattern":"〜でも（suggestion）","romaji":"de mo (suggestion)","level":"N4","ru":"или что-нибудь (смягчение предложения)","en":"or something (softening a suggestion)","formation":"Noun + でも","formationRu":"существительное + でも","notes":"Предлагает один пример, оставляя открытыми другие варианты, поэтому приглашения и советы звучат менее навязчиво.","tags":["suggestion","example"],"ex":[{"ja":"ちょっと休んで、コーヒーでも飲みませんか。","fu":"ちょっと{休|やす}んで、コーヒーでも{飲|の}みませんか。","ru":"Может, немного отдохнём и выпьем кофе?"},{"ja":"雨だから、家でゲームでもしよう。","fu":"{雨|あめ}だから、{家|いえ}でゲームでもしよう。","ru":"Раз идёт дождь, давай поиграем дома."},{"ja":"暇なら、本でも読んだら？","fu":"{暇|ひま}なら、{本|ほん}でも{読|よ}んだら？","ru":"Если скучно, почему бы не почитать что-нибудь?"}]},{"id":"toka-toka","pattern":"〜とか〜とか","romaji":"toka ... toka","level":"N4","ru":"типа A и B; A, B и тому подобное (разговорное)","en":"things like A and B; A, B and so on (casual)","formation":"Noun + とか + Noun + とか / Verb-dict + とか + Verb-dict + とか","formationRu":"существительное + とか + существительное + とか / глагол в словарной форме + とか + глагол в словарной форме + とか","notes":"Разговорнее, чем 〜や〜など, и может перечислять тоже глаголы или целые конструкции.","tags":["example","casual"],"ex":[{"ja":"冷蔵庫に卵とか牛乳とかが入っています。","fu":"{冷蔵庫|れいぞうこ}に{卵|たまご}とか{牛乳|ぎゅうにゅう}とかが{入|はい}っています。","ru":"В холодильнике лежат яйца, молоко и тому подобное."},{"ja":"休みの日は、映画とか買い物とかに行きます。","fu":"{休|やす}みの{日|ひ}は、{映画|えいが}とか{買|か}い{物|もの}とかに{行|い}きます。","ru":"В свободные дни я хожу в кино, по магазинам и тому подобное."},{"ja":"健康のために、野菜を食べるとか運動するとか、何かしたほうがいい。","fu":"{健康|けんこう}のために、{野菜|やさい}を{食|た}べるとか{運動|うんどう}するとか、{何|なに}かしたほうがいい。","ru":"Ради здоровья лучше что-нибудь делать: есть овощи, заниматься спортом и тому подобное."}]},{"id":"toki","pattern":"〜とき","romaji":"toki","level":"N4","ru":"когда; в то время когда","en":"when; at the time when","formation":"Verb-plain / i-Adj / na-Adj + な / Noun + の + とき","formationRu":"простая форма / прилагательное на -い / прилагательное на -на + な / существительное + の + とき","notes":"Время глагола показывает порядок: 行くとき — до или по пути (действие ещё не завершено); 行ったとき — после прибытия. Часто записывается иероглифом 時.","tags":["time","sequence"],"ex":[{"ja":"子どものとき、よく川で泳ぎました。","fu":"{子|こ}どものとき、よく{川|かわ}で{泳|およ}ぎました。","ru":"В детстве я часто плавал в реке."},{"ja":"日本へ行くとき、新しいかばんを買いました。","fu":"{日本|にほん}へ{行|い}くとき、{新|あたら}しいかばんを{買|か}いました。","ru":"Перед поездкой в Японию я купил новую сумку."},{"ja":"日本へ行ったとき、友達にお土産を買いました。","fu":"{日本|にほん}へ{行|い}ったとき、{友達|ともだち}にお{土産|みやげ}を{買|か}いました。","ru":"Когда я был в Японии, я купил друзьям сувениры."}]},{"id":"tokoro-da","pattern":"〜ところだ","romaji":"tokoro da","level":"N4","ru":"вот-вот; как раз сейчас; только что","en":"be about to; be in the middle of; have just done","formation":"Verb-dict / Verb-te + いる / Verb-ta + ところだ","formationRu":"глагол в словарной форме / глагол в форме -て + いる / глагол в форме -た + ところだ","notes":"Словарная форма: вот-вот. 〜ているところ: как раз в процессе. 〜たところ: только что закончил. Указывает точную стадию действия.","tags":["time","state"],"ex":[{"ja":"今から出かけるところです。","fu":"{今|いま}から{出|で}かけるところです。","ru":"Я как раз собираюсь выйти."},{"ja":"今、晩ご飯を作っているところだから、後で電話するね。","fu":"{今|いま}、{晩|ばん}ご{飯|はん}を{作|つく}っているところだから、{後|あと}で{電話|でんわ}するね。","ru":"Я как раз готовлю ужин, поэтому позвоню позже."},{"ja":"ちょうど今、駅に着いたところです。","fu":"ちょうど{今|いま}、{駅|えき}に{着|つ}いたところです。","ru":"Я как раз сейчас пришёл на станцию."}]},{"id":"to-omou","pattern":"〜と思う","romaji":"to omou","level":"N4","ru":"думаю, что","en":"I think that","formation":"Verb-plain / i-Adj + と思う / na-Adj + だ + と思う / Noun + だ + と思う","formationRu":"простая форма / прилагательное на -い + と思う / прилагательное на -на + だ + と思う / существительное + だ + と思う","notes":"В японском обычно отрицается цитируемая часть (来ないと思う), а не само 思う. О чужом мнении говорят 〜と思っている.","tags":["quotation","conjecture"],"ex":[{"ja":"この映画はきっと人気が出ると思う。","fu":"この{映画|えいが}はきっと{人気|にんき}が{出|で}ると{思|おも}う。","ru":"Думаю, этот фильм наверняка станет популярным."},{"ja":"彼女は今日は来ないと思います。","fu":"{彼女|かのじょ}は{今日|きょう}は{来|こ}ないと{思|おも}います。","ru":"Думаю, сегодня она не придёт."},{"ja":"日本の電車はとても便利だと思います。","fu":"{日本|にほん}の{電車|でんしゃ}はとても{便利|べんり}だと{思|おも}います。","ru":"Думаю, японские поезда очень удобны."}]},{"id":"to-iu-say","pattern":"〜と言う","romaji":"to iu (say)","level":"N4","ru":"говорить, что; сообщить (цитата)","en":"say that; tell (quotation)","formation":"「Sentence」 + と言う / Sentence (plain) + と言う","formationRu":"「предложение」 + と言う / предложение (простая форма) + と言う","notes":"Прямая речь берётся в кавычки 「」; косвенная — в простых формах. 〜と言っていた часто передаёт чужие слова.","tags":["quotation"],"ex":[{"ja":"先生は「明日はテストがあります」と言いました。","fu":"{先生|せんせい}は「{明日|あした}はテストがあります」と{言|い}いました。","ru":"Учитель сказал: «Завтра будет контрольная»."},{"ja":"兄は今晩、帰りが遅くなると言っていた。","fu":"{兄|あに}は{今晩|こんばん}、{帰|かえ}りが{遅|おそ}くなると{言|い}っていた。","ru":"Брат говорил, что сегодня он вернётся поздно."},{"ja":"日本では食べる前に「いただきます」と言います。","fu":"{日本|にほん}では{食|た}べる{前|まえ}に「いただきます」と{言|い}います。","ru":"В Японии перед едой говорят «итадакимас»."}]},{"id":"to","pattern":"〜と（conditional）","romaji":"to","level":"N4","ru":"когда; если; всякий раз когда (естественный или автоматический результат)","en":"when; if; whenever (natural or automatic result)","formation":"Verb-dict / Verb-nai / i-Adj + と / na-Adj + だ + と / Noun + だ + と","formationRu":"глагол в словарной форме / глагол в форме -ない / прилагательное на -い + と / прилагательное на -на + だ + と / существительное + だ + と","notes":"Для естественных результатов, работы механизмов, инструкций и привычек. Главная часть не может быть просьбой, желанием или приглашением.","tags":["condition"],"ex":[{"ja":"このボタンを押すと、お茶が出ます。","fu":"このボタンを{押|お}すと、お{茶|ちゃ}が{出|で}ます。","ru":"Если нажать эту кнопку, польётся чай."},{"ja":"春になると、桜が咲きます。","fu":"{春|はる}になると、{桜|さくら}が{咲|さ}きます。","ru":"Когда приходит весна, зацветает сакура."},{"ja":"この道を右に曲がると、左に郵便局があります。","fu":"この{道|みち}を{右|みぎ}に{曲|ま}がると、{左|ひだり}に{郵便|ゆうびん}{局|きょく}があります。","ru":"Если на этой дороге повернуть направо, слева будет почта."}]},{"id":"naide","pattern":"〜ないで","romaji":"naide","level":"N4","ru":"не делая; вместо того чтобы делать","en":"without doing; instead of doing","formation":"Verb-nai + で","formationRu":"глагол в форме -ない + で","notes":"〜ずに (N3) то же по смыслу, но формальнее. Отличается от 〜なくて, которое называет причину.","tags":["negation","manner"],"ex":[{"ja":"今朝は朝ご飯を食べないで学校に行った。","fu":"{今朝|けさ}は{朝|あさ}ご{飯|はん}を{食|た}べないで{学校|がっこう}に{行|い}った。","ru":"Сегодня утром я пошёл в школу без завтрака."},{"ja":"傘を持たないで出かけて、雨にぬれてしまった。","fu":"{傘|かさ}を{持|も}たないで{出|で}かけて、{雨|あめ}にぬれてしまった。","ru":"Я вышел без зонта и промок под дождём."},{"ja":"エレベーターを使わないで、階段で上がりましょう。","fu":"エレベーターを{使|つか}わないで、{階段|かいだん}で{上|あ}がりましょう。","ru":"Давайте поднимемся по лестнице, а не на лифте."}]},{"id":"nai-to-ikenai-nakucha","pattern":"〜ないといけない / 〜なくちゃ","romaji":"nai to ikenai / nakucha","level":"N4","ru":"должен; надо (разговорное)","en":"have to; must (conversational)","formation":"Verb-nai + といけない / Verb-nai stem + なくちゃ","formationRu":"глагол в форме -ない + といけない / основа формы -ない + なくちゃ","notes":"Повседневные варианты вместо なければならない. なくちゃ восходит к なくては; なきゃ (от なければ) тоже очень частое.","tags":["obligation","casual"],"ex":[{"ja":"明日は早いから、もう寝ないといけない。","fu":"{明日|あした}は{早|はや}いから、もう{寝|ね}ないといけない。","ru":"Завтра рано вставать, поэтому уже нужно ложиться спать."},{"ja":"あ、もうこんな時間！帰らなくちゃ。","fu":"あ、もうこんな{時間|じかん}！{帰|かえ}らなくちゃ。","ru":"Ой, уже столько времени! Пора домой."},{"ja":"この薬は毎日飲まないといけません。","fu":"この{薬|くすり}は{毎日|まいにち}{飲|の}まないといけません。","ru":"Это лекарство нужно принимать каждый день."}]},{"id":"nasai","pattern":"〜なさい","romaji":"nasai","level":"N4","ru":"сделай (указание родителя, учителя и т. п.)","en":"do (instruction from a parent, teacher, etc.)","formation":"Verb-stem + なさい","formationRu":"основа масу-формы + なさい","notes":"Мягче повелительной формы, но всё же твёрдое указание; так говорят родители и учителя, так формулируют задания на экзамене; по отношению к старшим не употребляется.","tags":["command"],"ex":[{"ja":"もう九時よ。早く寝なさい。","fu":"もう{九|く}{時|じ}よ。{早|はや}く{寝|ね}なさい。","ru":"Уже девять. Ложись-ка спать пораньше."},{"ja":"次の文を読んで、質問に答えなさい。","fu":"{次|つぎ}の{文|ぶん}を{読|よ}んで、{質問|しつもん}に{答|こた}えなさい。","ru":"Прочитай следующий текст и ответь на вопросы."},{"ja":"ご飯の前に手を洗いなさい。","fu":"ご{飯|はん}の{前|まえ}に{手|て}を{洗|あら}いなさい。","ru":"Перед едой вымой руки."}]},{"id":"nado","pattern":"〜など","romaji":"nado","level":"N4","ru":"и так далее; и прочее; такие как","en":"etc.; and so on; such as","formation":"Noun + など","formationRu":"существительное + など","notes":"Часто в паре с や (AやBなど). После одного существительного смягчает предложение.","tags":["example"],"ex":[{"ja":"机の上に本やノートなどがあります。","fu":"{机|つくえ}の{上|うえ}に{本|ほん}やノートなどがあります。","ru":"На столе лежат книги, тетради и тому подобное."},{"ja":"夏休みに京都や奈良などに行きました。","fu":"{夏休|なつやす}みに{京都|きょうと}や{奈良|なら}などに{行|い}きました。","ru":"На летних каникулах я побывал в Киото, Наре и других местах."},{"ja":"お茶など、いかがですか。","fu":"お{茶|ちゃ}など、いかがですか。","ru":"Может быть, чаю?"}]},{"id":"nara","pattern":"〜なら","romaji":"nara","level":"N4","ru":"если (имеется в виду, что); если говорить о","en":"if (it's the case that); if you're talking about","formation":"Verb-plain / i-Adj / na-Adj / Noun + なら","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + なら","notes":"Подхватывает сказанное собеседником или предполагаемое положение дела и даёт совет или мнение. В отличие от たら, главное действие может стоять перед придаточным с なら.","tags":["condition","topic"],"ex":[{"ja":"京都へ行くなら、秋がいいですよ。","fu":"{京都|きょうと}へ{行|い}くなら、{秋|あき}がいいですよ。","ru":"Если поедешь в Киото, лучше поехать осенью."},{"ja":"パソコンのことなら、兄に聞くといいよ。","fu":"パソコンのことなら、{兄|あに}に{聞|き}くといいよ。","ru":"Если речь о компьютере, спроси у старшего брата."},{"ja":"そんなに眠いなら、今日は早く寝たら？","fu":"そんなに{眠|ねむ}いなら、{今日|きょう}は{早|はや}く{寝|ね}たら？","ru":"Если так хочется спать, почему бы сегодня не лечь пораньше?"}]},{"id":"na-prohibition","pattern":"〜な（prohibition）","romaji":"na (prohibition)","level":"N4","ru":"не делай! (сильный запрет)","en":"don't! (strong prohibition)","formation":"Verb-dict + な","formationRu":"глагол в словарной форме + な","notes":"Очень сильный и резкий. Не путать с финальным な, выражающим чувство (いいな).","tags":["prohibition","command"],"ex":[{"ja":"危ないから、この川では泳ぐな。","fu":"{危|あぶ}ないから、この{川|かわ}では{泳|およ}ぐな。","ru":"Это опасно, так что в этой реке не плавай."},{"ja":"もう泣くな。大丈夫だよ。","fu":"もう{泣|な}くな。{大丈夫|だいじょうぶ}だよ。","ru":"Не плачь больше. Всё в порядке."},{"ja":"壁に「ここにごみを捨てるな」と書いてある。","fu":"{壁|かべ}に「ここにごみを{捨|す}てるな」と{書|か}いてある。","ru":"На стене написано: «Здесь мусор не выбрасывать»."}]},{"id":"no-koto-nominalizer","pattern":"〜の / 〜こと（nominalizer）","romaji":"no / koto (nominalizer)","level":"N4","ru":"действие (превращает глагольную конструкцию в существительное)","en":"the act of doing (turns a verb phrase into a noun)","formation":"Verb-plain + の / Verb-plain + こと","formationRu":"простая форма + の / простая форма + こと","notes":"の предпочтительно с глаголами восприятия (見る, 聞こえる) и в разговорной речи; こと нужно перед です/だ и в устойчивых конструкциях вроде 〜ことができる.","tags":["nominalization"],"ex":[{"ja":"私は写真を撮るのが好きです。","fu":"{私|わたし}は{写真|しゃしん}を{撮|と}るのが{好|す}きです。","ru":"Я люблю фотографировать."},{"ja":"趣味は古い映画を見ることです。","fu":"{趣味|しゅみ}は{古|ふる}い{映画|えいが}を{見|み}ることです。","ru":"Моё увлечение — смотреть старые фильмы."},{"ja":"かぎをかけるのを忘れました。","fu":"かぎをかけるのを{忘|わす}れました。","ru":"Я забыл запереть дверь на замок."}]},{"id":"node","pattern":"〜ので","romaji":"node","level":"N4","ru":"потому что; так как","en":"because; since","formation":"Verb-plain / i-Adj + ので / na-Adj + な + ので / Noun + な + ので","formationRu":"простая форма / прилагательное на -い + ので / прилагательное на -на + な + ので / существительное + な + ので","notes":"Звучит мягче и объективнее, чем から, поэтому предпочтительно, когда вежливо объясняют причину или извиняются.","tags":["reason"],"ex":[{"ja":"頭が痛いので、今日は早く帰ります。","fu":"{頭|あたま}が{痛|いた}いので、{今日|きょう}は{早|はや}く{帰|かえ}ります。","ru":"У меня болит голова, поэтому сегодня я вернусь пораньше."},{"ja":"明日はテストなので、今夜は勉強します。","fu":"{明日|あした}はテストなので、{今夜|こんや}は{勉強|べんきょう}します。","ru":"Завтра контрольная, поэтому сегодня вечером я буду заниматься."},{"ja":"道がこんでいたので、少し遅れました。","fu":"{道|みち}がこんでいたので、{少|すこ}し{遅|おく}れました。","ru":"Дорога была загружена, поэтому я немного опоздал."}]},{"id":"noni-although","pattern":"〜のに（although）","romaji":"noni (although)","level":"N4","ru":"хотя; несмотря на то что (с удивлением или недовольством)","en":"although; even though (with surprise or dissatisfaction)","formation":"Verb-plain / i-Adj + のに / na-Adj + な + のに / Noun + な + のに","formationRu":"простая форма / прилагательное на -い + のに / прилагательное на -на + な + のに / существительное + な + のに","notes":"Несёт удивление, разочарование или жалобу. Главная часть не может быть просьбой или намерением — там берут けど или ても.","tags":["concession","criticism"],"ex":[{"ja":"一生懸命勉強したのに、試験に落ちてしまった。","fu":"{一生懸命|いっしょうけんめい}{勉強|べんきょう}したのに、{試験|しけん}に{落|お}ちてしまった。","ru":"Я так старательно готовился, но всё-таки провалил экзамен."},{"ja":"日曜日なのに、会社に行かなければならない。","fu":"{日曜日|にちようび}なのに、{会社|かいしゃ}に{行|い}かなければならない。","ru":"Воскресенье, а приходится идти на работу."},{"ja":"約束したのに、彼は来なかった。","fu":"{約束|やくそく}したのに、{彼|かれ}は{来|こ}なかった。","ru":"Мы договорились, но он так и не пришёл."}]},{"id":"noni-purpose","pattern":"〜のに（purpose）","romaji":"noni (purpose)","level":"N4","ru":"для; чтобы (о применении, времени или затратах)","en":"for; in order to (with use, time or cost)","formation":"Verb-dict + のに / Noun + に","formationRu":"глагол в словарной форме + のに / существительное + に","notes":"Обычно за ним идут слова вроде 使う, いい, 便利, 必要 или かかる. С существительным используется просто に (旅行に便利).","tags":["purpose"],"ex":[{"ja":"このかばんは旅行に行くのに便利です。","fu":"このかばんは{旅行|りょこう}に{行|い}くのに{便利|べんり}です。","ru":"Эта сумка удобна для поездки."},{"ja":"家から駅まで歩くのに二十分かかります。","fu":"{家|いえ}から{駅|えき}まで{歩|ある}くのに{二十分|にじゅっぷん}かかります。","ru":"Пешком от дома до станции идёт двадцать минут."},{"ja":"引っ越しするのに十万円ぐらいかかった。","fu":"{引|ひ}っ{越|こ}しするのに{十|じゅう}{万|まん}{円|えん}ぐらいかかった。","ru":"Переезд обошёлся примерно в сто тысяч иен."}]},{"id":"hazu-ga-nai","pattern":"〜はずがない","romaji":"hazu ga nai","level":"N4","ru":"не может быть; быть того не может","en":"can't be; there's no way that","formation":"Verb-plain / i-Adj + はずがない / na-Adj + な + はずがない / Noun + の + はずがない","formationRu":"простая форма / прилагательное на -い + はずがない / прилагательное на -на + な + はずがない / существительное + の + はずがない","notes":"Резкое отрицание, основанное на рассуждении. 〜ないはずだ («не должно быть») — более мягкое ожидание.","tags":["conjecture","negation"],"ex":[{"ja":"あんなにまじめな人がうそをつくはずがない。","fu":"あんなにまじめな{人|ひと}がうそをつくはずがない。","ru":"Такой честный человек не может обманывать."},{"ja":"今日は日曜日だから、銀行が開いているはずがない。","fu":"{今日|きょう}は{日曜日|にちようび}だから、{銀行|ぎんこう}が{開|あ}いているはずがない。","ru":"Сегодня воскресенье, банк не может быть открыт."},{"ja":"かぎはちゃんとかけたから、ドアが開いているはずがない。","fu":"かぎはちゃんとかけたから、ドアが{開|あ}いているはずがない。","ru":"Я как следует запер дверь, значит, она не может быть открыта."}]},{"id":"hazu-da","pattern":"〜はずだ","romaji":"hazu da","level":"N4","ru":"должно быть; ожидается (вывод из рассуждения)","en":"should be; is expected to (based on reasoning)","formation":"Verb-plain / i-Adj + はずだ / na-Adj + な + はずだ / Noun + の + はずだ","formationRu":"простая форма / прилагательное на -い + はずだ / прилагательное на -на + な + はずだ / существительное + の + はずだ","notes":"Уверенное ожидание, основанное на фактах или логике, а не догадка. Не означает «должен» в смысле обязанности.","tags":["conjecture"],"ex":[{"ja":"荷物は明日届くはずです。","fu":"{荷物|にもつ}は{明日|あした}{届|とど}くはずです。","ru":"Посылка должна прийти завтра."},{"ja":"彼は十年もアメリカに住んでいたから、英語が上手なはずだ。","fu":"{彼|かれ}は{十|じゅう}{年|ねん}もアメリカに{住|す}んでいたから、{英語|えいご}が{上手|じょうず}なはずだ。","ru":"Он десять лет жил в Америке, значит, должен хорошо знать английский."},{"ja":"おかしいな。かぎはここに置いたはずなのに。","fu":"おかしいな。かぎはここに{置|お}いたはずなのに。","ru":"Странно. Я ведь оставил ключ именно здесь."}]},{"id":"ba","pattern":"〜ば","romaji":"ba","level":"N4","ru":"если","en":"if","formation":"Verb-ba / i-Adj stem + ければ / na-Adj + なら / Noun + なら","formationRu":"условная форма (-ば) / основа прилагательного на -い + ければ / прилагательное на -на + なら / существительное + なら","notes":"Акцент на условии, необходимом для результата. Если главная часть — просьба или приглашение, обычно естественнее たら, разве что придаточное с ば обозначает состояние (ある, いる, прилагательные).","tags":["condition"],"ex":[{"ja":"この道をまっすぐ行けば、駅に着きます。","fu":"この{道|みち}をまっすぐ{行|い}けば、{駅|えき}に{着|つ}きます。","ru":"Если идти прямо по этой дороге, придёшь на станцию."},{"ja":"安ければ、買いたいです。","fu":"{安|やす}ければ、{買|か}いたいです。","ru":"Если будет недорого, я хотел бы это купить."},{"ja":"分からないことがあれば、いつでも聞いてください。","fu":"{分|わ}からないことがあれば、いつでも{聞|き}いてください。","ru":"Если что-нибудь непонятно, всегда спрашивайте."}]},{"id":"bakari","pattern":"〜ばかり","romaji":"bakari","level":"N4","ru":"только; один лишь; ничего, кроме","en":"nothing but; only; all","formation":"Noun + ばかり","formationRu":"существительное + ばかり","notes":"Часто подразумевает, что чего-то слишком много. 〜てばかりいる (N3) и 〜たばかり («только что сделал») — отдельные пункты.","tags":["limitation","criticism"],"ex":[{"ja":"弟は肉ばかり食べて、野菜を食べない。","fu":"{弟|おとうと}は{肉|にく}ばかり{食|た}べて、{野菜|やさい}を{食|た}べない。","ru":"Брат ест одно только мясо и совсем не ест овощей."},{"ja":"このクラスは女の子ばかりだ。","fu":"このクラスは{女|おんな}の{子|こ}ばかりだ。","ru":"В этом классе одни только девочки."},{"ja":"最近は雨の日ばかりで、洗濯ができない。","fu":"{最近|さいきん}は{雨|あめ}の{日|ひ}ばかりで、{洗濯|せんたく}ができない。","ru":"В последнее время идут одни дожди, и нельзя постирать."}]},{"id":"ba-yokatta","pattern":"〜ばよかった","romaji":"ba yokatta","level":"N4","ru":"надо было (сделать); жаль, что не сделал","en":"should have (done); I wish I had","formation":"Verb-ba + よかった / Verb-nai stem + なければよかった","formationRu":"условная форма (-ば) + よかった / основа формы -ない + なければよかった","notes":"Выражает сожаление о прошлом. 〜たらよかった — распространённая разговорная замена.","tags":["regret"],"ex":[{"ja":"もっと早く家を出ればよかった。","fu":"もっと{早|はや}く{家|いえ}を{出|で}ればよかった。","ru":"Надо было выйти из дома пораньше."},{"ja":"あんなこと、言わなければよかった。","fu":"あんなこと、{言|い}わなければよかった。","ru":"Не надо было говорить такие вещи."},{"ja":"傘を持ってくればよかったなあ。","fu":"{傘|かさ}を{持|も}ってくればよかったなあ。","ru":"Надо было взять с собой зонт!"}]},{"id":"hou-ga-ii","pattern":"〜ほうがいい","romaji":"hou ga ii","level":"N4","ru":"лучше бы; следует","en":"had better; should","formation":"Verb-ta / Verb-nai + ほうがいい","formationRu":"глагол в форме -た / глагол в форме -ない + ほうがいい","notes":"Для совета обычно выбирают прошедшую форму (行ったほうがいい), она звучит сильнее. В отрицании берётся форма на -ない, а не прошедшая.","tags":["advice"],"ex":[{"ja":"熱があるなら、病院に行ったほうがいいですよ。","fu":"{熱|ねつ}があるなら、{病院|びょういん}に{行|い}ったほうがいいですよ。","ru":"Если у тебя жар, лучше обратиться к врачу."},{"ja":"夜遅くに一人で歩かないほうがいい。","fu":"{夜|よる}{遅|おそ}くに{一人|ひとり}で{歩|ある}かないほうがいい。","ru":"Не стоит ходить одному поздно ночью."},{"ja":"大事な書類は、コピーしておいたほうがいいですよ。","fu":"{大事|だいじ}な{書類|しょるい}は、コピーしておいたほうがいいですよ。","ru":"Важные документы лучше на всякий случай скопировать."}]},{"id":"hodo-nai","pattern":"〜ほど〜ない","romaji":"hodo ... nai","level":"N4","ru":"не так ..., как","en":"not as ... as","formation":"Noun / Verb-plain + ほど + i-Adj-ku + ない / na-Adj + ではない","formationRu":"существительное / простая форма + ほど + прилагательное на -い в форме -く + ない / прилагательное на -на + ではない","notes":"Стоящее перед ほど служит эталоном сравнения. Всегда с отрицанием.","tags":["comparison","negation"],"ex":[{"ja":"今年の夏は去年ほど暑くない。","fu":"{今年|ことし}の{夏|なつ}は{去年|きょねん}ほど{暑|あつ}くない。","ru":"В этом году лето не такое жаркое, как в прошлом."},{"ja":"私の町は東京ほどにぎやかではありません。","fu":"{私|わたし}の{町|まち}は{東京|とうきょう}ほどにぎやかではありません。","ru":"Мой городок не так оживлён, как Токио."},{"ja":"テストは思ったほど難しくなかった。","fu":"テストは{思|おも}ったほど{難|むずか}しくなかった。","ru":"Тест оказался не таким сложным, как я думал."}]},{"id":"made-ni","pattern":"〜までに","romaji":"made ni","level":"N4","ru":"к (сроку); до (какого-то момента)","en":"by (a deadline); before","formation":"Noun / Verb-dict + までに","formationRu":"существительное / глагол в словарной форме + までに","notes":"までに отмечает срок одноразового действия; まで — как долго что-то продолжается (六時まで働く).","tags":["time"],"ex":[{"ja":"レポートは金曜日までに出してください。","fu":"レポートは{金曜日|きんようび}までに{出|だ}してください。","ru":"Пожалуйста, сдайте реферат не позже пятницы."},{"ja":"六時までに家に帰らなければならない。","fu":"{六|ろく}{時|じ}までに{家|いえ}に{帰|かえ}らなければならない。","ru":"Мне нужно вернуться домой не позже шести часов."},{"ja":"暗くなるまでに山を下りよう。","fu":"{暗|くら}くなるまでに{山|やま}を{下|お}りよう。","ru":"Спустимся с горы, пока не стемнело."}]},{"id":"mitai","pattern":"〜みたい","romaji":"mitai","level":"N4","ru":"похоже на; как будто (разговорное)","en":"seems like; looks like; like (casual)","formation":"Verb-plain / i-Adj / na-Adj / Noun + みたい","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + みたい","notes":"Разговорный эквивалент ようだ. Присоединяется напрямую к существительным и на-прилагательным (静かみたい) без な и の. Перед существительным становится みたいな.","tags":["conjecture","appearance","casual"],"ex":[{"ja":"隣の部屋に誰か来たみたい。","fu":"{隣|となり}の{部屋|へや}に{誰|だれ}か{来|き}たみたい。","ru":"Кажется, в соседнюю комнату кто-то пришёл."},{"ja":"今日の彼女は元気がないみたいだね。","fu":"{今日|きょう}の{彼女|かのじょ}は{元気|げんき}がないみたいだね。","ru":"Кажется, сегодня у неё совсем нет сил."},{"ja":"このケーキ、お店のケーキみたい！","fu":"このケーキ、お{店|みせ}のケーキみたい！","ru":"Этот торт как из кондитерской!"}]},{"id":"mo-emphasis","pattern":"〜も（emphasis）","romaji":"mo (emphasis)","level":"N4","ru":"целых; столько много; (с отрицанием) ни одного","en":"as many as; as much as; (with a negative) not even one","formation":"Noun (number + counter) + も","formationRu":"существительное (число + счётное слово) + も","notes":"Показывает, что говорящему количество кажется большим. С 一 + счётное слово и отрицательным глаголом означает «ни одного».","tags":["emphasis","quantity"],"ex":[{"ja":"昨日は十時間も寝てしまった。","fu":"{昨日|きのう}は{十|じゅう}{時間|じかん}も{寝|ね}てしまった。","ru":"Вчера я проспал целых десять часов."},{"ja":"このかばんは五万円もするんですか。","fu":"このかばんは{五|ご}{万|まん}{円|えん}もするんですか。","ru":"Неужели эта сумка стоит целых пятьдесят тысяч иен?"},{"ja":"財布の中に一円もない。","fu":"{財布|さいふ}の{中|なか}に{一|いち}{円|えん}もない。","ru":"В кошельке нет ни единой иены."}]},{"id":"yasui-nikui","pattern":"〜やすい / 〜にくい","romaji":"yasui / nikui","level":"N4","ru":"легко делать; трудно делать","en":"easy to; hard to","formation":"Verb-stem + やすい / Verb-stem + にくい","formationRu":"основа масу-формы + やすい / основа масу-формы + にくい","notes":"Оба изменяются как и-прилагательные. やすい может также означать «легко подвержен» (この服は汚れやすい).","tags":["degree","tendency"],"ex":[{"ja":"このペンは書きやすいです。","fu":"このペンは{書|か}きやすいです。","ru":"Этой ручкой удобно писать."},{"ja":"先生の説明は分かりやすい。","fu":"{先生|せんせい}の{説明|せつめい}は{分|わ}かりやすい。","ru":"Учитель объясняет понятно."},{"ja":"この魚は骨が多くて食べにくい。","fu":"この{魚|さかな}は{骨|ほね}が{多|おお}くて{食|た}べにくい。","ru":"У этой рыбы много костей, её трудно есть."}]},{"id":"you-da","pattern":"〜ようだ","romaji":"you da","level":"N4","ru":"похоже; кажется (суждение по признакам)","en":"it seems; it appears (judging from evidence)","formation":"Verb-plain / i-Adj + ようだ / na-Adj + な + ようだ / Noun + の + ようだ","formationRu":"простая форма / прилагательное на -い + ようだ / прилагательное на -на + な + ようだ / существительное + の + ようだ","notes":"Несколько формальный способ высказать вывод из наблюдаемого или ощущаемого; разговорный эквивалент — みたいだ. Значение «подобно, как будто» разбирается на уровне N3.","tags":["conjecture","appearance"],"ex":[{"ja":"誰もいないようですね。","fu":"{誰|だれ}もいないようですね。","ru":"Похоже, здесь никого нет."},{"ja":"かぜをひいたようで、朝からのどが痛い。","fu":"かぜをひいたようで、{朝|あさ}からのどが{痛|いた}い。","ru":"Похоже, я простудился: с утра болит горло."},{"ja":"外は寒いようだ。みんなコートを着ている。","fu":"{外|そと}は{寒|さむ}いようだ。みんなコートを{着|き}ている。","ru":"На улице, похоже, холодно: все в пальто."}]},{"id":"you-ni-suru","pattern":"〜ようにする","romaji":"you ni suru","level":"N4","ru":"стараться; следить за тем, чтобы; сделать привычкой","en":"try to; make sure to; make a habit of","formation":"Verb-dict / Verb-nai + ようにする","formationRu":"глагол в словарной форме / глагол в форме -ない + ようにする","notes":"〜ようにしている описывает привычку, которую вы поддерживаете. Сравни 〜ようになる — изменение, которое происходит само.","tags":["attempt","intention"],"ex":[{"ja":"毎日野菜を食べるようにしています。","fu":"{毎日|まいにち}{野菜|やさい}を{食|た}べるようにしています。","ru":"Я стараюсь есть овощи каждый день."},{"ja":"これからは遅刻しないようにします。","fu":"これからは{遅刻|ちこく}しないようにします。","ru":"С этого времени я постараюсь не опаздывать."},{"ja":"寝る前にスマホを見ないようにしている。","fu":"{寝|ね}る{前|まえ}にスマホを{見|み}ないようにしている。","ru":"Я стараюсь не смотреть в телефон перед сном."}]},{"id":"you-ni-naru","pattern":"〜ようになる","romaji":"you ni naru","level":"N4","ru":"стать способным; прийти к тому, что (изменение умения или привычки)","en":"come to; reach the point where (change in ability or habit)","formation":"Verb-dict / Verb-nai + ようになる","formationRu":"глагол в словарной форме / глагол в форме -ない + ようになる","notes":"Часто с потенциальными глаголами. Для «больше не» обычно естественнее 〜なくなる, чем 〜ないようになる.","tags":["change","ability"],"ex":[{"ja":"練習して、自転車に乗れるようになりました。","fu":"{練習|れんしゅう}して、{自転車|じてんしゃ}に{乗|の}れるようになりました。","ru":"Я потренировался и теперь умею ездить на велосипеде."},{"ja":"日本に来てから、朝ご飯を食べるようになった。","fu":"{日本|にほん}に{来|き}てから、{朝|あさ}ご{飯|はん}を{食|た}べるようになった。","ru":"С тех пор как приехал в Японию, я стал завтракать."},{"ja":"赤ちゃんが少しずつ話せるようになってきた。","fu":"{赤|あか}ちゃんが{少|すこ}しずつ{話|はな}せるようになってきた。","ru":"Малыш понемногу начинает говорить."}]},{"id":"you-ni","pattern":"〜ように（purpose）","romaji":"you ni","level":"N4","ru":"чтобы (о том, что нельзя контролировать напрямую)","en":"so that; in order that","formation":"Verb-dict / Verb-nai + ように","formationRu":"глагол в словарной форме / глагол в форме -ない + ように","notes":"Употребляется с глаголами, которые субъект не контролирует напрямую: потенциальные формы, 分かる, 見える, отрицания. Для намеренных действий — ために.","tags":["purpose"],"ex":[{"ja":"後ろの人にも聞こえるように、大きな声で話してください。","fu":"{後|うし}ろの{人|ひと}にも{聞|き}こえるように、{大|おお}きな{声|こえ}で{話|はな}してください。","ru":"Говорите громко, чтобы было слышно и тем, кто сидит сзади."},{"ja":"忘れないように、手にメモを書いた。","fu":"{忘|わす}れないように、{手|て}にメモを{書|か}いた。","ru":"Чтобы не забыть, я написал записку на руке."},{"ja":"かぜをひかないように、暖かくして寝てください。","fu":"かぜをひかないように、{暖|あたた}かくして{寝|ね}てください。","ru":"Чтобы не простудиться, ложитесь спать потеплее."}]},{"id":"rashii","pattern":"〜らしい（hearsay/conjecture）","romaji":"rashii","level":"N4","ru":"по-видимому; похоже; по слухам","en":"apparently; it seems; I hear","formation":"Verb-plain / i-Adj / na-Adj / Noun + らしい","formationRu":"простая форма / прилагательное на -い / прилагательное на -на / существительное + らしい","notes":"Основано на услышанном или прочитанном, поэтому говорящий звучит несколько отстранённо. らしい в значении «типичный для» (男らしい) — отдельный пункт уровня N3.","tags":["hearsay","conjecture"],"ex":[{"ja":"駅の近くに新しいカフェができたらしい。","fu":"{駅|えき}の{近|ちか}くに{新|あたら}しいカフェができたらしい。","ru":"По-видимому, рядом со станцией открылось новое кафе."},{"ja":"部屋の電気が消えている。もう寝たらしい。","fu":"{部屋|へや}の{電気|でんき}が{消|き}えている。もう{寝|ね}たらしい。","ru":"Свет в комнате выключен. По-видимому, уже легли спать."},{"ja":"あの店のラーメンはとても有名らしいです。","fu":"あの{店|みせ}のラーメンはとても{有名|ゆうめい}らしいです。","ru":"По-видимому, рамен в том ресторане очень знаменит."}]},{"id":"reru-rareru-passive","pattern":"〜れる / 〜られる（passive）","romaji":"reru / rareru (passive)","level":"N4","ru":"быть сделанным (кем-то); страдательный залог","en":"be done (by someone); passive voice","formation":"Verb-nai stem + れる (Group 1) / Verb-nai stem + られる (Group 2)","formationRu":"основа формы -ない + れる (1-я группа) / основа формы -ない + られる (2-я группа)","notes":"Неправильные: する → される, 来る → 来られる. Производитель действия отмечается частицей に. Часто показывает, что субъект пострадал от чужого действия (雨に降られた).","tags":["voice","conjugation"],"ex":[{"ja":"先生に作文をほめられました。","fu":"{先生|せんせい}に{作文|さくぶん}をほめられました。","ru":"Учитель похвалил моё сочинение."},{"ja":"電車の中で足を踏まれた。","fu":"{電車|でんしゃ}の{中|なか}で{足|あし}を{踏|ふ}まれた。","ru":"В поезде мне наступили на ногу."},{"ja":"この寺は六百年前に建てられました。","fu":"この{寺|てら}は{六百|ろっぴゃく}{年|ねん}{前|まえ}に{建|た}てられました。","ru":"Этот храм был построен шестьсот лет назад."}]},{"id":"n-desu-no-desu","pattern":"〜んです / 〜のです","romaji":"n desu / no desu","level":"N4","ru":"дело в том, что...; (объяснение или просьба объяснить)","en":"it's that ...; (explaining or asking for an explanation)","formation":"Verb-plain / i-Adj + んです / na-Adj + な + んです / Noun + な + んです","formationRu":"простая форма / прилагательное на -い + んです / прилагательное на -на + な + んです / существительное + な + んです","notes":"Добавляет оттенок объяснения ситуации или вопроса о её причине. Разговорные варианты — 〜んだ и 〜の. Чрезмерное употребление может прозвучать навязчиво.","tags":["reason","emphasis"],"ex":[{"ja":"どうしたんですか。顔色が悪いですよ。","fu":"どうしたんですか。{顔色|かおいろ}が{悪|わる}いですよ。","ru":"Что с вами? У вас такой плохой цвет лица."},{"ja":"すみません、遅れました。電車が止まっていたんです。","fu":"すみません、{遅|おく}れました。{電車|でんしゃ}が{止|と}まっていたんです。","ru":"Извините, я опоздал. Поезд стоял."},{"ja":"日本語で手紙を書きたいんですが、手伝ってくれませんか。","fu":"{日本語|にほんご}で{手紙|てがみ}を{書|か}きたいんですが、{手伝|てつだ}ってくれませんか。","ru":"Я хочу написать письмо по-японски, не могли бы вы мне помочь?"}]},{"id":"chuu-juu","pattern":"〜中","romaji":"chuu / juu","level":"N4","ru":"посреди; в течение (ちゅう); в течение всего, по всей (じゅう)","en":"in the middle of; during (ちゅう); throughout; all over (じゅう)","formation":"Noun + 中","formationRu":"существительное + 中","notes":"ちゅう отмечает идущее действие или период (会議中, 午前中, 今週中); じゅう означает «в течение всего» времени или «по всей» территории (一日中, 世界中).","tags":["time","range"],"ex":[{"ja":"父は今、電話中です。","fu":"{父|ちち}は{今|いま}、{電話|でんわ}{中|ちゅう}です。","ru":"Отец сейчас разговаривает по телефону."},{"ja":"昨日は一日中雨が降っていた。","fu":"{昨日|きのう}は{一日中|いちにちじゅう}{雨|あめ}が{降|ふ}っていた。","ru":"Вчера дождь шёл весь день."},{"ja":"この歌は世界中で知られている。","fu":"この{歌|うた}は{世界中|せかいじゅう}で{知|し}られている。","ru":"Эта песня известна во всём мире."}]},{"id":"yotei","pattern":"〜予定","romaji":"yotei","level":"N4","ru":"планировать; быть запланированным","en":"plan to; be scheduled to","formation":"Verb-dict + 予定 / Noun + の + 予定","formationRu":"глагол в словарной форме + 予定 / существительное + の + 予定","notes":"Указывает на фиксированный график или договорённость, часто с участием других людей; объективнее, чем つもり.","tags":["intention","time"],"ex":[{"ja":"来月、大阪に引っ越す予定です。","fu":"{来月|らいげつ}、{大阪|おおさか}に{引|ひ}っ{越|こ}す{予定|よてい}です。","ru":"В следующем месяце я планирую переехать в Осаку."},{"ja":"会議は三時に終わる予定です。","fu":"{会議|かいぎ}は{三|さん}{時|じ}に{終|お}わる{予定|よてい}です。","ru":"Совещание, по плану, закончится в три часа."},{"ja":"出発は朝八時の予定です。","fu":"{出発|しゅっぱつ}は{朝|あさ}{八|はち}{時|じ}の{予定|よてい}です。","ru":"Отправление запланировано на восемь часов утра."}]},{"id":"dasu","pattern":"〜出す","romaji":"dasu","level":"N4","ru":"внезапно начать; броситься делать","en":"suddenly start doing; burst out","formation":"Verb-stem + 出す","formationRu":"основа масу-формы + 出す","notes":"Подразумевает внезапное, часто неконтролируемое начало. В отличие от 〜始める, не употребляется с запланированными действиями и в просьбах.","tags":["time","surprise"],"ex":[{"ja":"赤ちゃんが急に泣き出した。","fu":"{赤|あか}ちゃんが{急|きゅう}に{泣|な}き{出|だ}した。","ru":"Малыш вдруг заплакал."},{"ja":"さっきまで晴れていたのに、急に雨が降り出した。","fu":"さっきまで{晴|は}れていたのに、{急|きゅう}に{雨|あめ}が{降|ふ}り{出|だ}した。","ru":"Ещё недавно было ясно, но вдруг пошёл дождь."}]},{"id":"hajimeru-owaru-tsuzukeru","pattern":"〜始める / 〜終わる / 〜続ける","romaji":"hajimeru / owaru / tsuzukeru","level":"N4","ru":"начать делать; закончить делать; продолжать делать","en":"start doing; finish doing; keep doing","formation":"Verb-stem + 始める / Verb-stem + 終わる / Verb-stem + 続ける","formationRu":"основа масу-формы + 始める / основа масу-формы + 終わる / основа масу-формы + 続ける","notes":"〜終わる употребляется с действиями, у которых есть явный конец (読む, 食べる, 書く). 〜終える — более формальная замена.","tags":["time","sequence"],"ex":[{"ja":"去年からギターを習い始めました。","fu":"{去年|きょねん}からギターを{習|なら}い{始|はじ}めました。","ru":"В прошлом году я начал заниматься гитарой."},{"ja":"その本、読み終わったら貸してくれない？","fu":"その{本|ほん}、{読|よ}み{終|お}わったら{貸|か}してくれない？","ru":"Дочитаешь эту книгу — не одолжишь её мне?"},{"ja":"三時間も歩き続けて、足が痛くなった。","fu":"{三|さん}{時間|じかん}も{歩|ある}き{続|つづ}けて、{足|あし}が{痛|いた}くなった。","ru":"Я шёл без передышки целых три часа, и у меня заболели ноги."}]},{"id":"kata","pattern":"〜方","romaji":"kata","level":"N4","ru":"как сделать; способ делать","en":"how to; way of doing","formation":"Verb-stem + 方","formationRu":"основа масу-формы + 方","notes":"Результат — существительное, поэтому дополнение берёт の вместо を (日本語の話し方). У глаголов на する: 勉強のしかた.","tags":["manner","nominalization"],"ex":[{"ja":"この機械の使い方を教えてください。","fu":"この{機械|きかい}の{使|つか}い{方|かた}を{教|おし}えてください。","ru":"Объясните, пожалуйста, как пользоваться этим прибором."},{"ja":"この漢字の読み方が分かりません。","fu":"この{漢字|かんじ}の{読|よ}み{方|かた}が{分|わ}かりません。","ru":"Я не знаю, как читается этот иероглиф."},{"ja":"祖母においしいみそ汁の作り方を習った。","fu":"{祖母|そぼ}においしいみそ{汁|しる}の{作|つく}り{方|かた}を{習|なら}った。","ru":"Бабушка научила меня вкусно готовить суп мисо."}]},{"id":"me","pattern":"〜目","romaji":"me","level":"N4","ru":"-й по счёту (первый, второй, третий ...)","en":"-th (ordinal: first, second, third ...)","formation":"Noun (number + counter) + 目","formationRu":"существительное (число + счётное слово) + 目","notes":null,"tags":["quantity"],"ex":[{"ja":"右から三つ目の建物が図書館です。","fu":"{右|みぎ}から{三|みっ}つ{目|め}の{建物|たてもの}が{図書館|としょかん}です。","ru":"Третье здание справа — библиотека."},{"ja":"日本に来るのは今回で二回目です。","fu":"{日本|にほん}に{来|く}るのは{今回|こんかい}で{二|に}{回|かい}{目|め}です。","ru":"Я приезжаю в Японию во второй раз."},{"ja":"二つ目の角を左に曲がってください。","fu":"{二|ふた}つ{目|め}の{角|かど}を{左|ひだり}に{曲|ま}がってください。","ru":"На втором перекрёстке поверните налево."}]},{"id":"aida-aida-ni","pattern":"〜間 / 〜間に","romaji":"aida / aida ni","level":"N4","ru":"пока; в течение (всё время); в какой-то момент в течение","en":"while; during (the whole time); at some point during","formation":"Verb-te + いる / Verb-dict / Noun + の + 間（に）","formationRu":"глагол в форме -て + いる / глагол в словарной форме / существительное + の + 間（に）","notes":"間 означает, что действие продолжается всё это время; 間に — что оно происходит в какой-то момент внутри периода.","tags":["time","simultaneity"],"ex":[{"ja":"夏休みの間、祖父の家にいました。","fu":"{夏休|なつやす}みの{間|あいだ}、{祖父|そふ}の{家|いえ}にいました。","ru":"Во время летних каникул я был у деда."},{"ja":"母が寝ている間に、部屋を掃除した。","fu":"{母|はは}が{寝|ね}ている{間|あいだ}に、{部屋|へや}を{掃除|そうじ}した。","ru":"Пока мама спала, я убрал комнату."},{"ja":"電車を待っている間、ずっと本を読んでいた。","fu":"{電車|でんしゃ}を{待|ま}っている{間|あいだ}、ずっと{本|ほん}を{読|よ}んでいた。","ru":"Пока я ждал поезд, я всё время читал книгу."}]},{"id":"ageru-kureru-morau","pattern":"あげる / くれる / もらう","romaji":"ageru / kureru / morau","level":"N4","ru":"дать (кому-то другому); дать (мне или моим близким); получить","en":"give (to someone else); give (to me or my group); receive","formation":"Noun (receiver) + に + Noun + を + あげる / Noun (giver) + が + Noun + を + くれる / Noun (giver) + に + Noun + を + もらう","formationRu":"существительное (получатель) + に + существительное + を + あげる / существительное (дающий) + が + существительное + を + くれる / существительное (дающий) + に + существительное + を + もらう","notes":"くれる употребляется только тогда, когда получатель — сам говорящий или кто-то из его окружения. При もらう дающий может быть помечен частицами に или から.","tags":["giving-receiving"],"ex":[{"ja":"私は弟に古いゲームをあげた。","fu":"{私|わたし}は{弟|おとうと}に{古|ふる}いゲームをあげた。","ru":"Я подарил младшему брату старую игру."},{"ja":"姉が誕生日にかわいいかばんをくれました。","fu":"{姉|あね}が{誕生|たんじょう}{日|び}にかわいいかばんをくれました。","ru":"Старшая сестра подарила мне на день рождения милую сумку."},{"ja":"友達から旅行のおみやげをもらった。","fu":"{友達|ともだち}から{旅行|りょこう}のおみやげをもらった。","ru":"Я получил от друга сувенир из поездки."}]},{"id":"o-suru","pattern":"お〜する","romaji":"o ... suru","level":"N4","ru":"(скромно) я делаю (для уважаемого человека)","en":"(humble) I do (for someone respected)","formation":"お + Verb-stem + する / ご + Noun + する","formationRu":"お + основа масу-формы + する / ご + существительное + する","notes":"Только о действиях, которые касаются собеседника или приносят ему пользу. お〜いたします ещё более формально.","tags":["humble"],"ex":[{"ja":"重そうですね。お持ちしましょうか。","fu":"{重|おも}そうですね。お{持|も}ちしましょうか。","ru":"Похоже, вам тяжело. Позвольте мне поднести."},{"ja":"後で詳しくご説明します。","fu":"{後|あと}で{詳|くわ}しくご{説明|せつめい}します。","ru":"Позже я всё подробно вам объясню."},{"ja":"駅までお送りします。","fu":"{駅|えき}までお{送|おく}りします。","ru":"Я провожу вас до станции."}]},{"id":"o-ni-naru","pattern":"お〜になる","romaji":"o ... ni naru","level":"N4","ru":"(почтительно) уважаемый человек делает","en":"(honorific) someone respected does","formation":"お + Verb-stem + になる","formationRu":"お + основа масу-формы + になる","notes":"Не употребляется с односложными основами (見る, 寝る) и с глаголами, имеющими особые формы (行く → いらっしゃる). У существительных на する берут ご + существительное + になる (ご利用になる).","tags":["honorific"],"ex":[{"ja":"先生はもうお帰りになりました。","fu":"{先生|せんせい}はもうお{帰|かえ}りになりました。","ru":"Учитель уже ушёл домой."},{"ja":"この本をお読みになりましたか。","fu":"この{本|ほん}をお{読|よ}みになりましたか。","ru":"Вы уже прочли эту книгу?"},{"ja":"社長はいつもこのホテルにお泊まりになります。","fu":"{社長|しゃちょう}はいつもこのホテルにお{泊|と}まりになります。","ru":"Президент всегда останавливается в этом отеле."}]},{"id":"nakanaka-nai","pattern":"なかなか〜ない","romaji":"nakanaka ... nai","level":"N4","ru":"не так просто; никак не; с трудом","en":"not easily; just won't; not readily","formation":"なかなか + Verb-nai","formationRu":"なかなか + глагол в форме -ない","notes":"Показывает, что что-то происходит не так быстро или легко, как хотелось бы. С утвердительной формой なかなか означает «довольно» (なかなかおいしい).","tags":["negation","degree"],"ex":[{"ja":"バスがなかなか来ない。","fu":"バスがなかなか{来|こ}ない。","ru":"Автобус никак не приходит."},{"ja":"漢字がなかなか覚えられません。","fu":"{漢字|かんじ}がなかなか{覚|おぼ}えられません。","ru":"Кандзи никак не запоминаются."},{"ja":"子どもがなかなか寝てくれない。","fu":"{子|こ}どもがなかなか{寝|ね}てくれない。","ru":"Ребёнок никак не засыпает."}]},{"id":"sonkeigo","pattern":"尊敬語","romaji":"sonkeigo","level":"N4","ru":"почтительные глаголы; вежливый язык для действий других","en":"honorific verbs; respectful language for others' actions","formation":"いらっしゃる（行く・来る・いる） / 召し上がる（食べる・飲む） / おっしゃる（言う） / なさる（する） / ご覧になる（見る） / くださる（くれる）","formationRu":"いらっしゃる（行く・来る・いる） / 召し上がる（食べる・飲む） / おっしゃる（言う） / なさる（する） / ご覧になる（見る） / くださる（くれる）","notes":"Возвышают действия тех, кого вы уважаете: клиентов, учителей, начальства. К собственным действиям никогда не применяется.","tags":["honorific","politeness"],"ex":[{"ja":"社長は何時ごろいらっしゃいますか。","fu":"{社長|しゃちょう}は{何|なん}{時|じ}ごろいらっしゃいますか。","ru":"В котором часу обычно бывает президент компании?"},{"ja":"先生、どうぞ召し上がってください。","fu":"{先生|せんせい}、どうぞ{召|め}し{上|あ}がってください。","ru":"Учитель, пожалуйста, угощайтесь."},{"ja":"部長は会議でそうおっしゃいました。","fu":"{部長|ぶちょう}は{会議|かいぎ}でそうおっしゃいました。","ru":"Начальник отдела на совещании сказал именно так."}]},{"id":"kenjougo","pattern":"謙譲語","romaji":"kenjougo","level":"N4","ru":"скромные глаголы; смиренный язык для собственных действий","en":"humble verbs; modest language for one's own actions","formation":"参る（行く・来る） / おる（いる） / いただく（食べる・飲む・もらう） / 申す（言う） / いたす（する） / 拝見する（見る） / 伺う（聞く・訪ねる）","formationRu":"参る（行く・来る） / おる（いる） / いただく（食べる・飲む・もらう） / 申す（言う） / いたす（する） / 拝見する（見る） / 伺う（聞く・訪ねる）","notes":"Понижают ваши собственные действия — или действия вашей группы — перед тем, кого уважают. 参る, おる, 申す и いたす вообще придают речи формальность.","tags":["humble","politeness"],"ex":[{"ja":"明日の午後、そちらに伺います。","fu":"{明日|あした}の{午後|ごご}、そちらに{伺|うかが}います。","ru":"Завтра после полудня я зайду к вам."},{"ja":"初めまして。リンと申します。","fu":"{初|はじ}めまして。リンと{申|もう}します。","ru":"Здравствуйте! Позвольте представиться: меня зовут Лин."},{"ja":"お手紙、拝見しました。","fu":"お{手紙|てがみ}、{拝見|はいけん}しました。","ru":"Я прочёл ваше письмо."}]}];